local config = {
  ui_story_5058_50580101_1_dialog_content = "\"¿Cómo estás, viejo amigo? No he sabido de ti en mucho tiempo.\"",
  ui_story_5058_50580101_2_dialog_content = "\"Sigo siendo el mismo. Como sabes, nosotros los mercenarios recibimos muchas asignaciones extrañas.\"",
  ui_story_5058_50580101_3_dialog_content = "\"No tengo mucho tiempo libre, pero poder pintar un par de trazos al día es suficiente para mí.\"",
  ui_story_5058_50580101_4_dialog_content = "\"Es solo que no he podido conocer a alguien más que comparta mi interés en los insectos como tú lo haces.\"",
  ui_story_5058_50580101_X4_dialog_content = "\"Eso me hace sentir un poco solitario.\"",
  ui_story_5058_50580101_5_dialog_content = "\"Sin embargo, he hecho nuevos amigos, como PlayerName.\"",
  ui_story_5058_50580101_X5_dialog_content = "\"Te presentaré a los dos cuando tenga la oportunidad.\"",
  ui_story_5058_50580101_6_dialog_content = "\"Pero me desvío. He oído hablar de la mariposa llamada la <color=#FFB400>Diosa Denuo</color> últimamente.\"",
  ui_story_5058_50580101_7_dialog_content = "\"Un lugar llamado el <color=#FFB400>Resort del Valle Denuo</color> anunció que se podía ver la impresionante mariposa allí...\"",
  ui_story_5058_50580101_8_dialog_content = "\"También se afirmaba que ver uno traería buena suerte y las bendiciones de la diosa.\"",
  ui_story_5058_50580101_9_dialog_content = "\"Por supuesto, es obviamente puro bombo, pero recordé que mencionaste esta especie de mariposa.\"",
  ui_story_5058_50580101_10_dialog_content = "\"EveAunque nunca me revelaste la conexión entre ellos y tu enigmático lugar de origen...\"",
  ui_story_5058_50580101_11_dialog_content = "\"De todos modos, espero que la noticia te sea útil y tengamos la oportunidad de encontrarnos de nuevo.\"",
  ui_story_5058_50580101_12_dialog_content = "\"Esperando su respuesta.\"",
  ui_story_5058_50580101_13_dialog_content = "No puedo creer que alguien extrañaría a alguien como yo.",
  ui_story_5058_50580101_14_dialog_content = "Pero, ¿cómo te voy a explicar lo que estoy haciendo ahora, Luke...?",
  ui_story_5058_50580101_15_dialog_content = "¿Te importaría venir un momento, Cena?",
  ui_story_5058_50580101_16_dialog_content = "La <color=#FFB400>invitación</color> que mencioné está lista. ¡Por favor envíala por mí!",
  ui_story_5058_50580101_17_dialog_content = "¡Seguro, jefe, servirá!",
  ui_story_5058_50580101_18_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5058_50580101_19_dialog_content = "¿Estás seguro de que estamos en el lugar correcto, PlayerName? Ni siquiera veo algo que se parezca a una casa normal...",
  ui_story_5058_50580101_20_dialog_content = "Simplemente no me grita \"¡el resort premium para ver a la Diosa Denuo!\"",
  ui_story_5058_50580101_21_dialog_content = "Bueno, aquí es donde apuntaban las coordenadas...",
  ui_story_5058_50580101_22_dialog_content = "¿Compraste las entradas por canales legítimos?",
  ui_story_5058_50580101_23_option_content = "¡Me aseguré de eso!",
  ui_story_5058_50580101_24_dialog_content = "Entonces, ¿qué pasa con esa <color=#FFB400>invitación</color> que tienes en la mano?",
  ui_story_5058_50580101_25_dialog_content = "El resort me lo envió, así que debería ser legítimo, ¿cierto?",
  ui_story_5058_50580101_26_option_content = "Bueno...",
  ui_story_5058_50580101_27_dialog_content = "Recibí esta <color=#FFB400>invitación</color> para mí en el correo, así que debería ser legítima, ¿cierto?",
  ui_story_5058_50580101_28_dialog_content = "¿Eh? Déjame ver...",
  ui_story_5058_50580101_29_dialog_content = "\"Estimado PlayerName, nos complace anunciar que el muy esperado Denuo Valley Resort ¡finalmente está completado!\"",
  ui_story_5058_50580101_30_dialog_content = "\"Las instalaciones incluyen un enorme parque de atracciones y un hotel premium.\"",
  ui_story_5058_50580101_31_dialog_content = "\"¡Te invitamos sinceramente a experimentar todas las comodidades y servicios que tenemos para ofrecer en la casa, antes de abrir al público!\"",
  ui_story_5058_50580101_32_dialog_content = "\"Incluidos con esta invitación hay tres pases VIP. Por favor, siéntete libre de traer a familiares o amigos.\"",
  ui_story_5058_50580101_33_dialog_content = "\"¡Todo el personal del Denuo Valley Resort espera tu llegada!\"",
  ui_story_5058_50580101_34_dialog_content = "\"Propietario Principal: Lorelei Cardogon\"",
  ui_story_5058_50580101_35_dialog_content = "Me preguntaba por qué tendrías entradas para un complejo turístico aún no inaugurado, PlayerName.",
  ui_story_5058_50580101_36_dialog_content = "Entonces en realidad eran pases gratis... Pensé que habías sacado de tus ahorros.",
  ui_story_5058_50580101_37_dialog_content = "Pero esto suena demasiado bueno para ser cierto. Creo que es una de esas estafas más recientes, o...",
  ui_story_5058_50580101_38_dialog_content = "Espera, ¿y si hay bandidos esperando para emboscarnos?",
  ui_story_5058_50580101_39_dialog_content = "Oye, espera. ¿No es este el territorio de Rediesel Wrench?",
  ui_story_5058_50580101_40_dialog_content = "<color=#e8d9bb>¡Chasquido!</color>",
  ui_story_5058_50580101_41_dialog_content = "¿De verdad vamos a atrapar bandidos?!",
  ui_story_5058_50580101_42_dialog_content = "¿Bandidos? Bueno, tienes toda la razón en el sentido de que un bandido está presente para robar los corazones de las señoras... pero ese no es el punto.",
  ui_story_5058_50580101_43_dialog_content = "Hemos estado esperando con ansias tu visita, PlayerName, y finalmente, aquí estás hoy.",
  ui_story_5058_50580101_44_dialog_content = "Las encantadoras jóvenes que están contigo deben ser Vice y Carleen, ¿supongo?",
  ui_story_5058_50580101_45_dialog_content = "¿Quién eres?",
  ui_story_5058_50580101_46_dialog_content = "Disculpa por no haberme presentado adecuadamente. Soy Cena, <color=#FFB400>gerente general</color> del Denuo Valley Resort.",
  ui_story_5058_50580101_47_dialog_content = "¡Oh, gracias al cielo, los pases eran legítimos! Pero, ¿realmente es este lugar un complejo turístico? No coincide exactamente con la descripción del folleto...",
  ui_story_5058_50580101_48_dialog_content = "Jajaja, el Valle Denuo puede ser bastante traicionero incluso para los Eclipsites. No es un lugar fácil de encontrar.",
  ui_story_5058_50580101_49_dialog_content = "EveAunque establecimos lanzaderas para nuestros huéspedes desde las cuatro esquinas del mundo...",
  ui_story_5058_50580101_50_dialog_content = "El jefe me instruyó específicamente que te recogiera personalmente, ya que eres nuestro VIP principal.",
  ui_story_5058_50580101_X50_dialog_content = "¿Nuestro estimado invitado tiene alguna pregunta?",
  ui_story_5058_50580101_51_option_content = "¿El jefe?",
  ui_story_5058_50580101_52_dialog_content = "¿Es esa la Sra. Lorelei Cardogon en la invitación?",
  ui_story_5058_50580101_53_dialog_content = "Sí. La señorita Lorelei es la hija mayor de la familia Cardogon y de la reputación en bienes raíces, además de ser la principal propietaria del complejo turístico Denuo Valley Resort.",
  ui_story_5058_50580101_54_dialog_content = "Se necesita alguien impresionante para construir un gran complejo turístico, pero esta es la primera vez que escucho este nombre.",
  ui_story_5058_50580101_55_dialog_content = "Lo cual no es inusual, en realidad. Los Cardogons son discretos, pero tienen inversiones en todo Astra. Su nombre generalmente solo es conocido por los expertos en negocios.",
  ui_story_5058_50580101_56_dialog_content = "Pero la señorita Lorelei no dependió de su familia para esta empresa. Ella misma consiguió inversiones externas para lanzar la instalación.",
  ui_story_5058_50580101_57_dialog_content = "¿Ella completa todo esto independientemente de su familia? ¡Eso es valiente!",
  ui_story_5058_50580101_X57_dialog_content = "Exactamente.",
  ui_story_5058_50580101_58_option_content = "¿Soy un VIP premier?",
  ui_story_5058_50580101_X59_dialog_content = "Eso es exagerado...",
  ui_story_5058_50580101_59_dialog_content = "PlayerName, tu reputación es conocida en todo Astra y se ha extendido incluso hasta el lejano oriente.",
  ui_story_5058_50580101_60_dialog_content = "El jefe ha sido un fan tuyo... No, ¿cuál es la palabra de nuevo?",
  ui_story_5058_50580101_61_dialog_content = "¡Ah, entendido, un Lovegator!",
  ui_story_5058_50580101_62_dialog_content = "¡Me halaga! Pero tu jefe seguro tiene una perspectiva amplia incluso para saber esas cosas.",
  ui_story_5058_50580101_X61_dialog_content = "¡Por cierto!",
  ui_story_5058_50580101_X62_dialog_content = "Oh, también mencionaste...",
  ui_story_5058_50580101_63_option_content = "¿Un transbordador?",
  ui_story_5058_50580101_64_dialog_content = "Eso significa que tenemos que tomar un paseo... ¿El complejo está lejos de aquí?",
  ui_story_5058_50580101_65_dialog_content = "No diría que está lejos, pero llegar allí podría ser un poco aventurero. Solo prepárate. Supongo que también podrías llamar al viaje una montaña rusa emocionante.",
  ui_story_5058_50580101_66_dialog_content = "¿No vamos a correr a cien millas por hora sobre este lugar árido y desolado de nuevo, verdad? ¿Dónde están las cascadas y lagos? ¿Dónde está el fresco verano que anhelaba?",
  ui_story_5058_50580101_67_dialog_content = "EveTodo lo que buscas está en el Valle de Denuo. Ya que estás ansioso por llegar allí, ¡entra en la lanzadera de una vez!",
  ui_story_5058_50580101_68_dialog_content = "Cuanto antes lleguemos, antes podremos empezar a divertirnos, ¿verdad?",
  ui_story_5058_50580101_69_dialog_content = "Vamos, no pongas cara de que vas a vomitar antes de subirte al coche. Solo para que sepas, a todos les gusta mi forma de conducir.",
  ui_story_5058_50580101_70_dialog_content = "Oh, una cosa más... Miren hacia aquí, estimados invitados, y digan, \"¡Queso!\"",
  ui_story_5058_50580101_71_dialog_content = "¿Ah?",
  ui_story_5058_50580101_72_dialog_content = "¡Tienes que tomar fotos para recordar las vacaciones!",
  ui_story_5058_50580101_73_dialog_content = "¡Qué reflexivo...! Tengo la sensación de que lo pasaremos genial aquí!",
  ui_story_5058_50580101_74_dialog_content = "Espero que sí.",
  ui_story_5058_50580101_75_dialog_content = "¡Hey, Carleen, no me mires así! Esta vez no pasará nada malo, ¿cierto? ¡Hey!",
  ui_story_5058_50580101_76_dialog_content = "<color=#828282>Crujido...</color>",
  ui_story_5058_50580101_77_dialog_content = "Estamos aquí, todos. Por favor, salgan del vehículo.",
  ui_story_5058_50580101_78_dialog_content = "Eh... ¿eso era... era eso tu \"gran manejo\" mencionado anteriormente?",
  ui_story_5058_50580101_79_dialog_content = "La-la-la, la-ta-ta-la-la... ♪",
  ui_story_5058_50580101_80_dialog_content = "¿Qué es eso?",
  ui_story_5058_50580101_81_dialog_content = "La-la-la, la-ta-ta-la-la ♪ El complejo Denuo Valley te da la bienvenida ♪",
  ui_story_5058_50580101_82_dialog_content = "¡Vaya, es igual que la imagen en el folleto!",
  ui_story_5058_50580101_83_dialog_content = "Acabamos de estar en un desierto árido y ahora todo es tan vibrante a nuestro alrededor... Es como si estuviéramos en un mundo diferente.",
  ui_story_5058_50580101_84_dialog_content = "¡Muchas gracias a todos ustedes, gente increíble, por elegir Denuo Valley Resort para comenzar sus fantásticas vacaciones! ¡Prepárense para diversión sin parar y aventuras épicas!",
  ui_story_5058_50580101_85_dialog_content = "Sí, exactamente, ¡diversión sin parar y aventuras épicas! Pero eso aún suena muy a huesos desnudos!",
  ui_story_5058_50580101_86_dialog_content = "\"Además, ofreceremos los servicios más exclusivos y suntuosos banquetes?\"",
  ui_story_5058_50580101_87_dialog_content = "Mmm. Cena, recuerda a la gente de publicidad que trabaje en el eslogan de entrada.",
  ui_story_5058_50580101_88_dialog_content = "Entendido, señorita Lorelei.",
  ui_story_5058_50580101_89_dialog_content = "¿Señorita Lorelei? Entonces, ¿eres la señorita Lorelei Cardogon, la dueña?",
  ui_story_5058_50580101_90_dialog_content = "<size=45>PlayerName, ¡por fin estás aquí!</size>",
  ui_story_5058_50580101_91_dialog_content = "¡Vaya, qué cola tan encantadora! Debes ser Vice.",
  ui_story_5058_50580101_92_dialog_content = "¡Y la etérea joven aquí debe ser Carleen!",
  ui_story_5058_50580101_93_dialog_content = "Me alegra haber tenido la previsión de incluir tres pases. Tenía la corazonada de que traerías a ambos, PlayerName!",
  ui_story_5058_50580101_94_dialog_content = "Agradezco que hayas tomado tiempo de tu ocupada agenda para asistir a nuestra apertura suave.",
  ui_story_5058_50580101_95_dialog_content = "Por favor, siéntanse como en casa. ¡Disfruten y pásenlo en grande!",
  ui_story_5058_50580101_96_dialog_content = "Bueno, gracias por invitarnos, señorita Lorelei. ¡Nunca he estado en un parque tan magnífico como este!",
  ui_story_5058_50580101_97_dialog_content = "Por favor, solo llámame Lorelei.",
  ui_story_5058_50580101_98_dialog_content = "Mmm, se supone que Teeny debe mostrarte el lugar... ¿Dónde está?",
  ui_story_5058_50580101_99_dialog_content = "De todos modos, ¡por favor adelante!",
  ui_story_5058_50580101_100_dialog_content = "...",
  ui_story_5058_50580101_101_dialog_content = "Oye, esa chica pelirroja por ahí...",
  ui_story_5058_50580101_102_option_content = "¡Creo que la conozco!",
  ui_story_5058_50580101_103_dialog_content = "¿No es eso Bopper?",
  ui_story_5058_50580101_104_dialog_content = "PlayerName... Por supuesto. Nadie más que tú me notaría de inmediato...",
  ui_story_5058_50580101_105_option_content = "Ella se ve familiar.",
  ui_story_5058_50580101_106_dialog_content = "Lo sabía... Supongo que ha pasado demasiado tiempo como para que te acuerdes de mí.",
  ui_story_5058_50580101_107_dialog_content = "Soy Bopper, PlayerName. Tú tienes el pájaro gigante y yo tengo mi Lagarto Gigante!",
  ui_story_5058_50580101_108_dialog_content = "Bopper, ¿de la Rediesel Wrench?!",
  ui_story_5058_50580101_109_dialog_content = "Ahí estás, Pequeño. ¡Te he estado buscando mucho!",
  ui_story_5058_50580101_110_dialog_content = "Pero he estado a su lado todo el tiempo, señorita Lorelei...",
  ui_story_5058_50580101_111_dialog_content = "¿También estás aquí para la apertura suave, Bopper?",
  ui_story_5058_50580101_112_dialog_content = "¡Ella es la especialista técnica que solicité específicamente de Rediesel Wrench!",
  ui_story_5058_50580101_113_dialog_content = "Bueno, en realidad soy más un mecánico general que el experto que la señorita Lorelei me hace parecer... Otros chicos de Rediesel Wrench también están aquí para ayudar.",
  ui_story_5058_50580101_114_dialog_content = "¿La gente de Rediesel Wrench está trabajando en trabajos regulares ahora? Esta podría ser mi oportunidad de atrapar a algunos de esos fugitivos buscados.",
  ui_story_5058_50580101_115_dialog_content = "Eh, Carleen, no nos enfoquemos en eso durante nuestras vacaciones, ¿de acuerdo?",
  ui_story_5058_50580101_116_dialog_content = "Nuestro personal del complejo ha pasado por exhaustivas verificaciones de antecedentes y entrenamiento. Nos encargaremos de cualquier problema que surja sin que tú tengas que mover un dedo.",
  ui_story_5058_50580101_117_dialog_content = "Perdón por interrumpir, señor. Tres clientes afuera están pidiendo específicamente verlo a usted...",
  ui_story_5058_50580101_118_dialog_content = "Creo que he terminado aquí, señorita Lorelei. Me voy a ocuparme de otros asuntos.",
  ui_story_5058_50580101_119_dialog_content = "PlayerName, señorita Vice y señorita Carleen, ¡les deseo a todas una divertida estancia por adelantado!",
  ui_story_5058_50580101_120_dialog_content = "¿No me digas que otro grupo de hermosas señoras acaba de llegar? Simplemente no sé qué hacer con él...",
  ui_story_5058_50580101_121_dialog_content = "Aunque no puedo creer la hora... ¿Por qué la reunión tenía que estar programada para ahora?",
  ui_story_5058_50580101_122_dialog_content = "¡Bueno, amigos, estoy feliz de tenerlos a todos aquí!",
  ui_story_5058_50580101_123_dialog_content = "Pero tengo que irme ahora. Cuando termine, te registraré en el hotel y te mostraré las atracciones.",
  ui_story_5058_50580101_124_dialog_content = "¡Puedes encargarte de aquí, Teeny!",
  ui_story_5058_50580101_125_dialog_content = "Ejem... simplemente llámame Bopper...",
  ui_story_5058_50580101_126_dialog_content = "Sabiendo que venías, me quedé despierto toda la noche y elaboré treinta y tres itinerarios.",
  ui_story_5058_50580101_127_dialog_content = "Combiné las preferencias personales de PlayerName, Vice y Carleen para obtener los mejores pasos y la ruta...",
  ui_story_5058_50580101_128_dialog_content = "Uh, no tienes que ser tan minucioso, Bopper. Podemos tomarlo con calma.",
  ui_story_5058_50580101_129_dialog_content = "¿Tomarlo con calma? Afortunadamente, también tengo un plan para eso.",
  ui_story_5058_50580101_130_dialog_content = "De acuerdo, entonces. Síganme, todos.",
  ui_story_5058_50580101_131_dialog_content = "¡Estamos a punto de embarcarnos en el itinerario más casual planeado!",
  ui_story_5058_50580201_1_dialog_content = "Estas son las fotos PlayerName que el Caelestite tomó en el camino al complejo turístico.",
  ui_story_5058_50580201_2_dialog_content = "También fotografiaremos el Caelestite con las diversas atracciones y comodidades del hotel.",
  ui_story_5058_50580201_3_dialog_content = "¡Entonces podemos poner un largometraje completo en su publicación!",
  ui_story_5058_50580201_4_dialog_content = "Eso tanto venderá el problema como incrementará la exposición para el complejo turístico.",
  ui_story_5058_50580201_5_dialog_content = "Hmm... Tengo que admitir que los Lovegators sí tienen cierto poder adquisitivo.",
  ui_story_5058_50580201_6_dialog_content = "Basado en nuestros hallazgos, los lugares que visita el Caelestite tienden a volverse virales, como la Isla de las Nubes, la Ciudad del Puerto...",
  ui_story_5058_50580201_7_dialog_content = "Eve¡n un lugar como Euforia floreció!",
  ui_story_5058_50580201_8_dialog_content = "Cierto, Harbor City es ahora el destino turístico más popular en Astra.",
  ui_story_5058_50580201_9_dialog_content = "¿Ciudad del Puerto? ¿Por qué me suena familiar?",
  ui_story_5058_50580201_10_dialog_content = "Tú, en una misión, decidiste unirte a una competencia a mitad de camino y casi terminas cayendo al agua.",
  ui_story_5058_50580201_11_dialog_content = "¡AHHH! ¡Los recuerdos de esos imprudentes plebeyos corriendo vienen a mi mente! ¡Cállate! ¡CÁLLATE!",
  ui_story_5058_50580201_12_dialog_content = "Lorelei, me alegra que hayas seguido nuestro consejo y utilizado a la Diosa Denuo como el avance en marketing del resort.",
  ui_story_5058_50580201_13_dialog_content = "Y realmente aprecio tu idea de aprovechar la reputación de Caelestite para la promoción.",
  ui_story_5058_50580201_14_dialog_content = "Pero sinceramente, estas son todas estrategias de marketing temporales y podrían no mantenerse a largo plazo.",
  ui_story_5058_50580201_15_dialog_content = "Todos sabemos que la Diosa Denuo es simplemente un cuento. ¿Quién sabe si siquiera existe?",
  ui_story_5058_50580201_16_dialog_content = "Por no mencionar, la popularidad del Caelestite podría no durar y podría convertirse en un gran dolor de cabeza algún día.",
  ui_story_5058_50580201_17_dialog_content = "El dinero que hemos invertido en el complejo turístico no es una suma insignificante...",
  ui_story_5058_50580201_18_dialog_content = "Entiendo lo que todos ustedes quieren como inversores.",
  ui_story_5058_50580201_19_dialog_content = "Para hacer que el complejo sea una operación sostenible, debemos garantizar servicios de calidad y proporcionar—",
  ui_story_5058_50580201_20_dialog_content = "No, lo que quiero decir es que deberíamos ofrecer algo más \"adictivo\"...",
  ui_story_5058_50580201_21_dialog_content = "...",
  ui_story_5058_50580201_22_dialog_content = "¿Estás seguro de que este es tu itinerario más informal, Bopper?",
  ui_story_5058_50580201_23_dialog_content = "Sí... Esta es la ruta que tomo cuando quiero relajarme, yo mismo.",
  ui_story_5058_50580201_24_dialog_content = "¡¿Realmente esto te relaja?!",
  ui_story_5058_50580201_25_dialog_content = "La Puerta de la Muerte es mi atracción favorita. ¡Algunas personas en Rediesel Wrench podrían montarla una docena de veces al día!",
  ui_story_5058_50580201_26_dialog_content = "Somos afortunados de que llegaste temprano. De lo contrario, tendríamos que esperar en una larga fila.",
  ui_story_5058_50580201_27_dialog_content = "¡Vaya, apenas puedo esperar! Apúrate, PlayerName.",
  ui_story_5058_50580201_28_dialog_content = "Creo que mis rodillas ya están cediendo...",
  ui_story_5058_50580201_29_dialog_content = "¿Qué? Pensé que estarías acostumbrado a esta altura con la frecuencia con la que pilotas el Águila Gigante...",
  ui_story_5058_50580201_30_dialog_content = "Ella tiene razón. Incluso has experimentado varios accidentes, así que esto debería ser pan comido para ti ahora.",
  ui_story_5058_50580201_31_dialog_content = "Hacer algo así activamente frente a no tener elección es completamente diferente...",
  ui_story_5058_50580201_32_dialog_content = "Relájate, ¡creo que estarás bien!",
  ui_story_5058_50580201_33_dialog_content = "En ese caso, creo que PlayerName debería enfrentarse al desafío más difícil!",
  ui_story_5058_50580201_34_dialog_content = "Después de que saltes, se liberarán muñecas inflables de Eclipsite a tu alrededor.",
  ui_story_5058_50580201_35_dialog_content = "Atrápalos en el camino hacia abajo para ganar pegatinas conmemorativas.",
  ui_story_5058_50580201_36_dialog_content = "Y, ¡también puedes llevarte a casa los Eclipsites inflables!",
  ui_story_5058_50580201_37_dialog_content = "¿Quién querría muñecas inflables que parezcan Eclipsitos?!",
  ui_story_5058_50580201_38_dialog_content = "¡Yo, yo, lo haría!",
  ui_story_5058_50580201_39_dialog_content = "¡Por favor, tráeme uno de regreso!",
  ui_story_5058_50580201_40_dialog_content = "¿Qué?",
  ui_story_5058_50580201_41_dialog_content = "¡Arghhhh—!",
  ui_story_5058_50580201_42_dialog_content = "¡Al menos podrías haberme dado una advertencia!",
  ui_story_5058_50580202_1_dialog_content = "¿Estás bien? Sigues frotándote los ojos... ¿estás llorando?",
  ui_story_5058_50580202_2_dialog_content = "¡No eso no es!",
  ui_story_5058_50580202_3_dialog_content = "Había todas estas luces parpadeando en mis ojos durante la caída...",
  ui_story_5058_50580202_4_dialog_content = "Oh, esa era una cámara tomando fotos. ¿Quieres ver las imágenes?",
  ui_story_5058_50580202_5_dialog_content = "Olvídalo, probablemente me veo incómodo...",
  ui_story_5058_50580202_6_dialog_content = "¡Mira todos los stickers que conseguí!",
  ui_story_5058_50580202_7_dialog_content = "¿Eh? ¿Ambos los consiguieron? ¡Felicidades por completar el juego!",
  ui_story_5058_50580202_8_dialog_content = "EveCada atracción en el parque tiene desafíos, y obtienes pegatinas al completarlos.",
  ui_story_5058_50580202_9_dialog_content = "Cuántas más pegatinas consigas, mejores premios podrás canjear.",
  ui_story_5058_50580202_10_dialog_content = "Oye, Carleen, ¿quieres ver quién consigue el mejor premio?",
  ui_story_5058_50580202_11_dialog_content = "Seguro, pero no consigas PlayerName para ayudarte.",
  ui_story_5058_50580202_12_dialog_content = "Sería un milagro si no tuviera que ayudar a PlayerName, y ni hablar de lo contrario.",
  ui_story_5058_50580202_13_dialog_content = "Oye, puedo escucharte, ¿sabes?",
  ui_story_5058_50580202_14_dialog_content = "Vaya, ¡la mariposa en esta pegatina seguro que es hermosa!",
  ui_story_5058_50580202_15_dialog_content = "Esa no es una mariposa común, sino la Diosa Denuo única del Valle Denuo.",
  ui_story_5058_50580202_16_dialog_content = "¿Realmente existe la Diosa Denuo?",
  ui_story_5058_50580202_17_dialog_content = "¡Creo que sí! Alguien acaba de decir que lo encontró en el resort recientemente...",
  ui_story_5058_50580202_18_dialog_content = "Y muchos turistas gastaron buen dinero en nuestra apertura suave solo por la oportunidad de verlo antes que nadie.",
  ui_story_5058_50580202_19_dialog_content = "Gracias a PlayerName, ¡no tuvimos que gastar nada! Pero me pregunto si lo veremos esta vez...",
  ui_story_5058_50580202_20_dialog_content = "Si es real, ¿por qué no mostrarlo al público?",
  ui_story_5058_50580202_21_dialog_content = "Todo ese bombo solo para dejarlo en un encuentro casual... Eso suena a estafa para mí.",
  ui_story_5058_50580202_22_dialog_content = "Vaya, debes ser el Caelestite que mencionó Cena. ¡Te pude reconocer a una milla de distancia en la multitud!",
  ui_story_5058_50580202_23_dialog_content = "¿Por qué te frotas los ojos? ¿Te duelen o algo así?",
  ui_story_5058_50580202_24_dialog_content = "Bueno, eh...",
  ui_story_5058_50580202_25_dialog_content = "Parece que es tu primera vez intentando el puenting.",
  ui_story_5058_50580202_26_dialog_content = "La primera vez puede ser un poco incómoda. ¿Esas personas junto a ti son tu familia o amigos? ¿Por qué parecen tan indiferentes?",
  ui_story_5058_50580202_27_dialog_content = "Pobrecito. Bueno, ya que no se preocupan por ti... déjanos darte un masaje relajante y ayudarte a relajarte.",
  ui_story_5058_50580202_28_dialog_content = "E-Está bien, gracias...",
  ui_story_5058_50580202_29_dialog_content = "¡Solo relájate! Nuestras habilidades de masaje son de primera categoría.",
  ui_story_5058_50580202_30_dialog_content = "V-Vice, Carleen... ¿Alguno de ustedes...",
  ui_story_5058_50580202_31_dialog_content = "Me preguntaba a dónde fueron las señoras. ¡No puedes acapararlas solo para ti, PlayerName!",
  ui_story_5058_50580202_32_dialog_content = "¿Qué pasa, pastelito? ¿Estás celoso?",
  ui_story_5058_50580202_33_dialog_content = "Suspiro, nunca pensé que llegaría el día en que sería el segundo mejor.",
  ui_story_5058_50580202_34_dialog_content = "Vamos, ¿cuándo empezaste a actuar tan posesivo? Aquí, déjame darte un masaje también, ¿de acuerdo?",
  ui_story_5058_50580202_35_dialog_content = "Sabía que era el favorito de Lina...",
  ui_story_5058_50580202_36_dialog_content = "S-Guárdame, Cena...",
  ui_story_5058_50580202_37_dialog_content = "¿Qué es eso, PlayerName? Vas a hacer que las señoras se sientan mal.",
  ui_story_5058_50580202_38_dialog_content = "¿De qué estás hablando? ¡Ni siquiera sé quiénes son!",
  ui_story_5058_50580202_39_dialog_content = "Solo quieres saber sus nombres. Jajaja, debería complacerte.",
  ui_story_5058_50580202_40_dialog_content = "Conocí a las tres señoras en viajes anteriores. A todas les encanta viajar.",
  ui_story_5058_50580202_41_dialog_content = "No dejes que sus modales te engañen. Son muy exigentes cuando se trata de viajes.",
  ui_story_5058_50580202_42_dialog_content = "Por eso invité específicamente a ellos al complejo como consultores.",
  ui_story_5058_50580202_43_dialog_content = "La lady con turbante es Winona. Pasamos mucho tiempo juntos en Northland buscando en ruinas antiguas. Estamos unidos como se puede estar.",
  ui_story_5058_50580202_44_dialog_content = "Winona actúa como nuestro consultor de seguridad.",
  ui_story_5058_50580202_45_dialog_content = "Mucho gusto.",
  ui_story_5058_50580202_46_dialog_content = "La masajista con las manos maravillosas es Lastelle. La acompañé antes cuando trabajaba como seguridad secreta en Lumopolis.",
  ui_story_5058_50580202_47_dialog_content = "Lastelle es un consultor de hospitalidad especializado en relajación. Además de eso—",
  ui_story_5058_50580202_48_dialog_content = "Muy bien, eso es suficiente. No reveles todos los secretos, querido. Solo quitará el elemento de sorpresa.",
  ui_story_5058_50580202_49_dialog_content = "Cuando era limpiador en el rural Umbraton, salvé a Lina de treinta asesinos. Ella es nuestra consultora gourmet.",
  ui_story_5058_50580202_50_dialog_content = "No tengo idea de por qué tanta gente intentaría matar a Lina. Ella es claramente la mujer más amable y gentil que he conocido.",
  ui_story_5058_50580202_51_dialog_content = "Je-je... Cena, nunca dejas de impresionar con tus palabras suaves, ¿verdad?",
  ui_story_5058_50580202_52_dialog_content = "¡No te quedes ahí parado! Ahora que estás aquí, ¡vamos a la parte divertida!",
  ui_story_5058_50580202_53_dialog_content = "Tienes razón. ¡Después de tanto hablar, deberíamos ver las atracciones!",
  ui_story_5058_50580202_54_dialog_content = "¿Por qué no vamos a algo más tranquilo... como la rueda de la fortuna de allá?",
  ui_story_5058_50580202_55_dialog_content = "Pero... tengo la rueda de la fortuna al final del itinerario.",
  ui_story_5058_50580202_56_dialog_content = "La vista desde allí es aún mejor por la noche debido a los fuegos artificiales nocturnos!",
  ui_story_5058_50580202_57_dialog_content = "¿Fuegos artificiales desde lo alto de la rueda de la fortuna? ¡Qué romántico!",
  ui_story_5058_50580202_58_dialog_content = "Fuegos artificiales, eh...",
  ui_story_5058_50580202_59_dialog_content = "¿Qué pasa, Cena? ¿No te gustan los espectáculos de fuegos artificiales?",
  ui_story_5058_50580202_60_dialog_content = "No... yo, eh, solo...",
  ui_story_5058_50580202_61_dialog_content = "Acabo de pensar en un lugar muy especial al que me gustaría llevar a las señoras.",
  ui_story_5058_50580202_62_dialog_content = "Espero que no me decepciones entonces.",
  ui_story_5058_50580202_63_dialog_content = "Claro que no. ¡Síganme, mis queridas señoras!",
  ui_story_5058_50580202_64_dialog_content = "É-Él se va, ¿así nomás?",
  ui_story_5058_50580202_65_dialog_content = "Está bien. Cena podría decir cosas inapropiadas, ¡pero sigue siendo una persona confiable!",
  ui_story_5058_50580202_66_dialog_content = "Él ayudó a Lorelei restaurar la ecología en el Valle de Denuo para que el complejo turístico pudiera lanzarse.",
  ui_story_5058_50580202_67_dialog_content = "¿Restaurar la ecología?",
  ui_story_5058_50580202_68_dialog_content = "No hace mucho tiempo, el Valle de Denuo todavía estaba árido.",
  ui_story_5058_50580202_69_dialog_content = "Pero Lorelei se enfocó en la tierra, invirtió una gran suma para mejorar el entorno y la restauró a lo que solía ser.",
  ui_story_5058_50580202_70_dialog_content = "Eso suena como mucho trabajo.",
  ui_story_5058_50580202_71_dialog_content = "Y Cena siempre podía encontrar una solución para completar cualquiera de las aparentemente locas exigencias de Lorelei.",
  ui_story_5058_50580202_72_dialog_content = "Even Sinsa le agradó lo suficiente como para intentar reclutarlo...",
  ui_story_5058_50580202_73_dialog_content = "¿No le dice eso Sinsa a cualquiera que conoce?",
  ui_story_5058_50580202_74_dialog_content = "Pero incluso entonces... Bueno, tal vez nunca debería juzgar un libro por su portada.",
  ui_story_5058_50580202_75_dialog_content = "<color=#e8d9bb>Salpicando—</color>",
  ui_story_5058_50580202_76_dialog_content = "Entonces, ¿este es el lugar especial del que hablabas?",
  ui_story_5058_50580202_77_dialog_content = "Sí. ¿No prefieren ustedes, señoras, nadar y tomar el sol en algún lugar tranquilo?",
  ui_story_5058_50580202_78_dialog_content = "La mayoría de los invitados están en el parque de atracciones, así que apenas hay alguien aquí en la piscina Oasis. Siéntanse libres de disfrutar.",
  ui_story_5058_50580202_79_dialog_content = "Cena, ¿por qué no te unes a nosotros para nadar también?",
  ui_story_5058_50580202_80_dialog_content = "Gracias, pero me temo que tengo que salir por el momento.",
  ui_story_5058_50580202_81_dialog_content = "La reunión de la Srta. Lorelei está a punto de terminar. Tengo que ir a averiguar qué resultó de ella.",
  ui_story_5058_50580202_82_dialog_content = "Vaya. Cena, ¿cuándo empezaste a gustarte las chicas más jóvenes?",
  ui_story_5058_50580202_83_dialog_content = "Entendería que viniera de otra persona, pero ¿no me digas que todavía no conoces mi gusto?",
  ui_story_5058_50580202_84_dialog_content = "Soy solo un trabajador que quiere mantener contento al jefe para poder ganar mucho dinero y complacerte a ti.",
  ui_story_5058_50580202_85_dialog_content = "¿En serio?",
  ui_story_5058_50580202_86_dialog_content = "Cena, claramente hay algo en tu mente que no quieres compartir con nosotros.",
  ui_story_5058_50580202_87_dialog_content = "Bueno, siempre que quieras, puedes venir a nosotros y hablar, ¿de acuerdo?",
  ui_story_5058_50580202_88_dialog_content = "Seguro. Disfruten y diviértanse, señoras. Por supuesto, ¡no escatimen en críticas y sugerencias!",
  ui_story_5058_50580301_1_dialog_content = "Oye, esto es raro, no te he visto tan infeliz en mucho tiempo.",
  ui_story_5058_50580301_2_dialog_content = "¿Qué dijeron los inversores en la reunión de la junta?",
  ui_story_5058_50580301_3_dialog_content = "¿Has oído hablar del <color=#FFB400>Incienso Denuo</color>?",
  ui_story_5058_50580301_4_dialog_content = "Incienso Denuo...",
  ui_story_5058_50580301_5_dialog_content = "Hmm, no puedo decir que lo haya hecho antes.",
  ui_story_5058_50580301_6_dialog_content = "Entonces, ¿tampoco tú sabes de eso? La Junta dijo que es una especia especial en Denuo y que fue una gran moda una vez.",
  ui_story_5058_50580301_7_dialog_content = "Quieren que lo produzcamos y lo lancemos a la luna como el producto estrella del complejo para así obtener negocios recurrentes.",
  ui_story_5058_50580301_8_dialog_content = "Vaya, eso va a ser difícil... ¿Qué les dijiste?",
  ui_story_5058_50580301_9_dialog_content = "Lo tendré en cuenta. Ya sabes cómo me han estado presionando para expandir el complejo turístico y desarrollar más del valle en la fase dos.",
  ui_story_5058_50580301_10_dialog_content = "Pero me prometieron que si fabricamos el Incienso Denuo, dejarán de interferir en los desarrollos futuros.",
  ui_story_5058_50580301_11_dialog_content = "Eso suena muy tentador, considerando las restricciones y condiciones que exigieron cuando comenzamos el proyecto.",
  ui_story_5058_50580301_12_dialog_content = "Sin embargo, tampoco ofrecieron ayuda sobre cómo proceder para hacer el incienso.",
  ui_story_5058_50580301_13_dialog_content = "Hablando de eso, el pueblo Denuo comerció con el mundo exterior durante un tiempo. Maytal vez alguien allí lo hizo.",
  ui_story_5058_50580301_14_dialog_content = "Pero el pueblo ya no existe. ¿Cómo vamos a encontrar la fórmula?",
  ui_story_5058_50580301_15_dialog_content = "Es verdad.",
  ui_story_5058_50580301_16_dialog_content = "No te preocupes, también me defiendo con las especias. Maytal vez pueda intentarlo.",
  ui_story_5058_50580301_17_dialog_content = "¿Incluso sabes de especias? ¡Qué hará el resort sin ti!",
  ui_story_5058_50580301_18_dialog_content = "Jaja, espero poder sacar un conejo del sombrero.",
  ui_story_5058_50580301_19_dialog_content = "¡Por favor! Even si no es totalmente perfecto, aún beneficiará al valle.",
  ui_story_5058_50580301_20_dialog_content = "No podemos abandonar nuestro plan de marketing original, sin embargo. El Caelestite sigue siendo el enfoque.",
  ui_story_5058_50580301_21_dialog_content = "¿Qué, no ganaste ninguna pegatina de Diosa Denuo en la Noche Blanca de Dragones?",
  ui_story_5058_50580301_22_dialog_content = "...",
  ui_story_5058_50580301_23_dialog_content = "Carleen se ve bastante pálido... ¿Las montañas rusas son demasiado para ti?",
  ui_story_5058_50580301_24_dialog_content = "¿Cómo es posible que alguien pueda manejar el puenting pero no una montaña rusa?",
  ui_story_5058_50580301_25_dialog_content = "Mayparece que hay un problema con el itinerario. Debería haber separado las categorías...",
  ui_story_5058_50580301_26_dialog_content = "¡Pero la Matriz de Fantasía que viene a continuación debería ofrecer una emoción totalmente diferente!",
  ui_story_5058_50580301_27_dialog_content = "¿Matriz de Fantasía? Finalmente, eso suena como un paseo simple y fácil. ¿Dónde está?",
  ui_story_5058_50580301_28_dialog_content = "¡Ta-da! Justo frente a nosotros. ¡Mira hacia arriba, PlayerName!",
  ui_story_5058_50580301_29_dialog_content = "¿Buscar...?",
  ui_story_5058_50580301_30_dialog_content = "¡Santo...! ¡Hablando de una sierra gigante! ¿Eso es un paseo? ¿Estás seguro?",
  ui_story_5058_50580301_31_dialog_content = "Sí, Sinsa diseñó esto, y como solía decir...",
  ui_story_5058_50580301_32_dialog_content = "Muy bien, granujas, ¡les espera la sierra si no son lo suficientemente rápidos para esquivar!",
  ui_story_5058_50580301_33_dialog_content = "Eve? No, eso no va para ti, Eve...!",
  ui_story_5058_50580301_34_dialog_content = "Sí, eso es algo que él diría.",
  ui_story_5058_50580301_35_dialog_content = "Esto es juego de niños. Veo que hay más pegatinas para mí.",
  ui_story_5058_50580301_36_dialog_content = "Ese es el Carleen que conozco. ¡Vamos, no puedo esperar!",
  ui_story_5058_50580301_37_dialog_content = "Entonces, antes de comenzar, ¡no olvides las medidas de seguridad!",
  ui_story_5058_50580301_38_dialog_content = "<color=#e8d9bb>Zumbido—</color>",
  ui_story_5058_50580301_39_dialog_content = "¡Apúrate, Carleen, o te voy a ganar!",
  ui_story_5058_50580301_40_dialog_content = "He estado listo. ¡Tú solo ten cuidado!",
  ui_story_5058_50580301_41_dialog_content = "Oye, espérame... ¿Por qué me dejan atrás de nuevo?",
  ui_story_5058_50580301_42_dialog_content = "Oye, chicos—",
  ui_story_5058_50580301_43_dialog_content = "Todos se fueron corriendo... Supongo que simplemente iré a vagar por mi cuenta.",
  ui_story_5058_50580301_44_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5058_50580301_45_dialog_content = "¡Dale crédito a la mejor tiradora del partido: Señorita Smokey!",
  ui_story_5058_50580301_46_dialog_content = "¡Felicidades, acabas de ganar otra pegatina de Denuo Goddess, 'ol gran Director Smokey!",
  ui_story_5058_50580301_47_dialog_content = "Me dejaste tomar los dos últimos tiros, ¿verdad, <color=#FFB400>Shashona</color>?",
  ui_story_5058_50580301_48_dialog_content = "¿Qué? ¡De ninguna manera! Eres un joven tirador experto, Director Smokey. Solo exageré un poco.",
  ui_story_5058_50580301_49_dialog_content = "Probablemente también puedas hacer trampa un poco en la Junta Directiva.",
  ui_story_5058_50580301_50_dialog_content = "Ah, ya veo de qué se trata esto.",
  ui_story_5058_50580301_51_dialog_content = "Bueno, la Junta está presionando a Lorelei para expandir el proyecto.",
  ui_story_5058_50580301_52_dialog_content = "Pero como todo empresario sabe, la celeridad genera desperdicio.",
  ui_story_5058_50580301_53_dialog_content = "¿Por qué no podemos simplemente construir la marca del complejo turístico y luego reinvertir el dinero en más proyectos?",
  ui_story_5058_50580301_54_dialog_content = "Apenas me interesa dirigir un negocio o escuchar sus sugerencias.",
  ui_story_5058_50580301_55_dialog_content = "Mientras las atracciones sean emocionantes y divertidas para mí, no me importa el resto.",
  ui_story_5058_50580301_56_dialog_content = "Hablando de eso, ninguna de las atracciones es lo suficientemente desafiante. Asegúrate de informar a Lorelei...",
  ui_story_5058_50580301_57_dialog_content = "Haz todo más difícil y agrega más trucos de puntuación. No todos tienen que ser disparos a grandes Eclipsites como Halo Shots. Eso es aburrido.",
  ui_story_5058_50580301_58_dialog_content = "¿Tú lo crees? Pensé que fue divertido jugar contigo. ¿Otra ronda?",
  ui_story_5058_50580301_59_dialog_content = "Objetivo a la vista—",
  ui_story_5058_50580301_60_dialog_content = "¿Qué objetivo? ¿Yo?",
  ui_story_5058_50580301_61_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_5058_50580301_62_dialog_content = "Recibí una invitación de Lorelei para la apertura suave. ¿Tú también recibiste una?",
  ui_story_5058_50580301_63_dialog_content = "A diferencia de ti, soy un director del complejo, aquí para revisar el progreso.",
  ui_story_5058_50580301_64_dialog_content = "¿Estás... en el Consejo de Administración?",
  ui_story_5058_50580301_65_dialog_content = "¿Por qué es una sorpresa? Claro, nunca lo he hecho, pero pensé que sería interesante invertir en un complejo turístico.",
  ui_story_5058_50580301_66_dialog_content = "Y gané en un casino recientemente con dinero en llamas en mi bolsillo, así que también podría gastarlo.",
  ui_story_5058_50580301_67_dialog_content = "Suena realmente bien ser rico...",
  ui_story_5058_50580301_68_dialog_content = "¿Eres tú... el Celestita? Estoy impresionado de que Lorelei logró traerte aquí.",
  ui_story_5058_50580301_69_dialog_content = "Uh, eres demasiado amable. Solo llámame PlayerName.",
  ui_story_5058_50580301_70_dialog_content = "¡Genial! Encantado de conocerte, PlayerName, soy Shashona.",
  ui_story_5058_50580301_71_dialog_content = "¡Por favor, disfruta! Hablemos de nuevo después de que hayas probado todas las atracciones.",
  ui_story_5058_50580301_72_dialog_content = "La Junta debería estar muy interesada en los comentarios de PlayerName, ¿cierto?",
  ui_story_5058_50580301_73_dialog_content = "Oye, ¿ya probaste Fantasy Matrix? Parece ser divertido.",
  ui_story_5058_50580301_74_dialog_content = "¿Por qué todos quieren eso? Preferiría probar algo diferente.",
  ui_story_5058_50580301_75_dialog_content = "Bueno entonces, prueba esto. No es difícil y debería ser fácil para ti.",
  ui_story_5058_50580301_76_dialog_content = "Simplemente apunta el arma a los Eclipsites y dispara sin parar.",
  ui_story_5058_50580301_77_dialog_content = "<color=#e8d9bb>¡Bang, bang!</color>",
  ui_story_5058_50580301_78_dialog_content = "¡Vaya, ya está empezando? Por cierto, ¡los Eclipsitas son tan reales como parece!",
  ui_story_5058_50580301_79_dialog_content = "Este es un concurso. Si ganas, ¡puedes montar la Matriz de Fantasía conmigo!",
  ui_story_5058_50580301_80_dialog_content = "No, está bien, todo lo que quiero son pegatinas...",
  ui_story_5058_50580402_1_dialog_content = "¡Oye, me has impresionado desde la última vez que te vi! Aunque no estás en mi liga.",
  ui_story_5058_50580402_2_dialog_content = "Uh, estoy seguro de que muy pocas personas podrían superarte en disparos.",
  ui_story_5058_50580402_3_dialog_content = "Jugué con casi todo y conseguí todas las pegatinas... ¿Qué queda por hacer?",
  ui_story_5058_50580402_4_dialog_content = "Hay muchas comodidades de hotel que vale la pena experimentar. ¿Qué tal recibir un masaje con aceite?",
  ui_story_5058_50580402_5_dialog_content = "Envié Lorelei a rogar al maestro en el lugar más renombrado para que haga a medida la esencia para el resort. No puedes conseguir eso en ningún otro lugar.",
  ui_story_5058_50580402_6_dialog_content = "Seguro, lo comprobaré. Hasta luego.",
  ui_story_5058_50580402_7_dialog_content = "¿También estarías interesado, viejo amigo de Smokey?",
  ui_story_5058_50580402_8_dialog_content = "Bueno, somos amigos, pero probablemente no lo suficientemente cercanos como para recibir un masaje juntos...",
  ui_story_5058_50580402_9_dialog_content = "Jeje, no hay problema. Los amigos a menudo van a jacuzzis, y ni hablar de masajes.",
  ui_story_5058_50580402_10_dialog_content = "Mayincluso puedes discutir posibles colaboraciones...",
  ui_story_5058_50580402_11_dialog_content = "Vaya, aún tienes negocios en mente en tu centro... Mucho más director que Smokey.",
  ui_story_5058_50580402_12_dialog_content = "Gracias por el cumplido, pero no soy un director, solo un pariente de Lorelei, para echar una mano amiga.",
  ui_story_5058_50580402_13_dialog_content = "Pariente de Lorelei, ya veo...",
  ui_story_5058_50580402_14_dialog_content = "¡PlayerName!",
  ui_story_5058_50580402_15_dialog_content = "¡Aquí estás! Nadie podía encontrarte y estábamos preocupados...",
  ui_story_5058_50580402_16_dialog_content = "Oh, lo siento. Cuando te subías a Fantasy Matrix, yo—",
  ui_story_5058_50580402_17_dialog_content = "¿Qué estás haciendo aquí?",
  ui_story_5058_50580402_18_dialog_content = "Oh, Laurie, ¿cómo es que no me dijiste que el complejo está abierto?",
  ui_story_5058_50580402_19_dialog_content = "La cantidad de invitados parece baja para una operación de esta escala.",
  ui_story_5058_50580402_20_dialog_content = "Es solo una apertura suave antes de la gran inauguración real. EveTodos aquí son solo por invitación.",
  ui_story_5058_50580402_21_dialog_content = "Ah, entonces acerté al pensar que este compañero está aquí para promocionar el parque?",
  ui_story_5058_50580402_22_dialog_content = "Obtienes un pase por hacer al Caelestite el portavoz del parque.",
  ui_story_5058_50580402_23_dialog_content = "Pero si me lo hubieras dicho antes, habría venido más temprano y personalmente habría mostrado a PlayerName los alrededores para que no haya ninguna persona solitaria...",
  ui_story_5058_50580402_24_dialog_content = "Sabía que harías eso, por eso—",
  ui_story_5058_50580402_25_dialog_content = "Mira tu tez, debes no estar adecuadamente hidratado.",
  ui_story_5058_50580402_26_dialog_content = "Traje algunos suplementos de casa. Los cocinaré para ti esta noche.",
  ui_story_5058_50580402_27_dialog_content = "Mamá, por favor no hables de eso al frente de un invitado. Ya soy lo suficientemente mayor para cuidar de mí mismo.",
  ui_story_5058_50580402_28_dialog_content = "(¿Q-Qué? ¿Shashona es la mamá de Lorelei?!)",
  ui_story_5058_50580402_29_dialog_content = "De todos modos, tengo que salir y llevar a nuestro invitado aquí para registrarse.",
  ui_story_5058_50580402_30_dialog_content = "Por aquí, por favor, PlayerName.",
  ui_story_5058_50580402_31_dialog_content = "Baja la velocidad, Laurie. ¿Por qué no llevas los zapatos que te compré? Ese par no es para trabajar...",
  ui_story_5058_50580402_32_dialog_content = "Uff.",
  ui_story_5058_50580402_33_dialog_content = "Tu mamá es muy buena contigo, Lorelei.",
  ui_story_5058_50580402_34_dialog_content = "Ella ciertamente lo es.",
  ui_story_5058_50580501_1_dialog_content = "De acuerdo, ya estás registrado.",
  ui_story_5058_50580501_2_dialog_content = "Gracias, Lorelei.",
  ui_story_5058_50580501_3_dialog_content = "Parte de mi trabajo, y siendo honesto, debería hacer más ya que eres nuestro VIP principal.",
  ui_story_5058_50580501_4_dialog_content = "Mmm, ¿ya te he explicado las características de las instalaciones del hotel?",
  ui_story_5058_50580501_5_dialog_content = "Ejem, además de cómodas y acogedoras habitaciones para huéspedes, el hotel también cuenta con un gimnasio, una piscina, aguas termales, spa...",
  ui_story_5058_50580501_6_dialog_content = "Hay marcas en las escaleras de cada nivel, así que no te preocupes por perderte.",
  ui_story_5058_50580501_7_dialog_content = "El interior también cuenta con el último sistema de ventilación, por lo que durante condiciones climáticas adversas como una tormenta de arena, lo utilizaremos para proporcionar aire fresco.",
  ui_story_5058_50580501_8_dialog_content = "No vas a experimentar ninguna molestia durante una estancia larga.",
  ui_story_5058_50580501_9_dialog_content = "Además, el desayuno y el almuerzo son tipo buffet, solo ve al restaurante y estarás bien...",
  ui_story_5058_50580501_10_dialog_content = "¡PlayerName!",
  ui_story_5058_50580501_11_dialog_content = "¿Dónde has estado? No pudimos encontrarte después de bajarnos del juego.",
  ui_story_5058_50580501_12_dialog_content = "Lo lamento... Estaba probando Halo Shots y conocí a una mujer llamada Shashona.",
  ui_story_5058_50580501_13_dialog_content = "Entonces Shashona está aquí.",
  ui_story_5058_50580501_14_dialog_content = "¿La conoces?",
  ui_story_5058_50580501_15_dialog_content = "¿Cómo lo digo...? No es alguien con quien debamos jugar.",
  ui_story_5058_50580501_16_dialog_content = "¿Por qué? ¿Es ella una pez gordo?",
  ui_story_5058_50580501_17_dialog_content = "Shashona es en realidad la mamá de Lorelei.",
  ui_story_5058_50580501_18_dialog_content = "¿La mamá de Lorelei también está aquí? ¿Cómo podemos celebrar el tiempo de Lorelei en ese caso?",
  ui_story_5058_50580501_19_dialog_content = "Bueno, deberíamos estar agradecidos de tener a Bopper con nosotros.",
  ui_story_5058_50580501_20_dialog_content = "Ejem... Gracias a todos. Por favor, sepan que mi misión es proporcionar un servicio de calidad a nuestros huéspedes. En cuanto a mi mamá... De hecho, viene a verme bastante a menudo.",
  ui_story_5058_50580501_21_dialog_content = "Oh, y me pregunto, ¿qué opinas sobre las atracciones?",
  ui_story_5058_50580501_22_dialog_content = "La verdad, muchas de esas cosas fueron demasiado para mí.",
  ui_story_5058_50580501_23_dialog_content = "Creo que son perfectamente emocionantes. Me divertí mucho.",
  ui_story_5058_50580501_24_dialog_content = "Puedo decir... Pero me canso solo de mirarlos y me encantaría un descanso ahora mismo.",
  ui_story_5058_50580501_25_dialog_content = "Ah, ah, ya veo.",
  ui_story_5058_50580501_26_dialog_content = "La Junta Directiva siempre quiso más atracciones emocionantes. Veo que necesitamos más atracciones para personas de todas las edades en cambio.",
  ui_story_5058_50580501_27_dialog_content = "(¿Personas de todas las edades? Tenemos más o menos la misma edad...!)",
  ui_story_5058_50580501_28_dialog_content = "¡Gracias por tus valiosos comentarios, PlayerName!",
  ui_story_5058_50580501_29_dialog_content = "¿Todos los demás están dejándolo por ahora, o deberíamos seguir probando las atracciones?",
  ui_story_5058_50580501_30_dialog_content = "Corrimos bastante y me siento un poco exhausto.",
  ui_story_5058_50580501_31_dialog_content = "Sí, estoy de acuerdo... ¡Pero aún no hemos recogido todas las pegatinas de la Diosa Denuo!",
  ui_story_5058_50580501_32_dialog_content = "Está bien, aún tienes varios días más para hacer eso.",
  ui_story_5058_50580501_33_dialog_content = "¡Genial, quiero recolectar todas las bonitas pegatinas de la Diosa Denuo!",
  ui_story_5058_50580501_34_dialog_content = "Hablando de eso, ¿quieren ustedes dar un paseo por el valle?",
  ui_story_5058_50580501_35_dialog_content = "Tiene muchas mariposas y tal vez veamos a la verdadera Diosa Denuo!",
  ui_story_5058_50580501_36_dialog_content = "Cuando descanses, puedo llevarte a conocer el valle.",
  ui_story_5058_50580501_37_dialog_content = "La zona aún está sin desarrollar, pero podría formar parte del complejo turístico en el futuro.",
  ui_story_5058_50580501_38_dialog_content = "¡Maravilloso! ¡Este viaje valdría mucho más la pena si viéramos a la Diosa Denuo!",
  ui_story_5058_50580501_39_dialog_content = "¿Por qué no vamos ahora?",
  ui_story_5058_50580501_40_dialog_content = "Estoy de acuerdo.",
  ui_story_5058_50580501_41_dialog_content = "¿No querías descansar un rato?",
  ui_story_5058_50580501_42_dialog_content = "Escuchamos que la señorita Lorelei dedicó mucho esfuerzo para volver verde el Valle de Denuo.",
  ui_story_5058_50580501_43_dialog_content = "¡Me emociono solo de pensar en el paisaje verde y exuberante!",
  ui_story_5058_50580501_44_dialog_content = "Yo también.",
  ui_story_5058_50580501_45_dialog_content = "Ya veo. ¿Por qué no? ¡Vamos a despegar ahora!",
  ui_story_5058_50580501_46_dialog_content = "<color=#e8d9bb>Después de un tiempo...</color>",
  ui_story_5058_50580501_47_dialog_content = "Respirar...",
  ui_story_5058_50580501_48_dialog_content = "El aire está tan limpio. Tomé una inhalación profunda y hasta mi boca se refrescó.",
  ui_story_5058_50580501_49_dialog_content = "El agradable aroma del césped me recuerda a Eraveil.",
  ui_story_5058_50580501_50_dialog_content = "Sí, las plantas parecen crecer de forma natural sin ningún signo de artificialidad.",
  ui_story_5058_50580501_51_dialog_content = "Eso es lo que se supone que es la naturaleza. Solo planta las semillas, aliméntalas y nos sorprenderán.",
  ui_story_5058_50580501_52_dialog_content = "Es impresionante, Lorelei, construir un complejo turístico como este en el Desierto de Rediesel. Pero, ¿qué te dio la idea?",
  ui_story_5058_50580501_53_dialog_content = "El propio Valle de Denuo tiene barreras geográficas para acordonar las incursiones de Eclipsita.",
  ui_story_5058_50580501_54_dialog_content = "Y el paisaje natural aquí es completamente diferente de otros lugares turísticos en Astra.",
  ui_story_5058_50580501_55_dialog_content = "Por lo tanto, un complejo turístico ofrecería una experiencia completamente diferente para los visitantes.",
  ui_story_5058_50580501_56_dialog_content = "Este también es un lugar muy importante para mí. Es mi deseo reanimar los alrededores...",
  ui_story_5058_50580501_57_dialog_content = "...",
  ui_story_5058_50580501_58_dialog_content = "Entiendo cómo te sientes. Es exactamente como me siento acerca de Eraveil.",
  ui_story_5058_50580501_59_dialog_content = "(¿Eso significa que de aquí es de donde era Lorelei?)",
  ui_story_5058_50580501_60_dialog_content = "Buen discurso, pero la señorita Lorelei es una empresaria en el corazón, así que todo se trata de ganancias.",
  ui_story_5058_50580501_61_dialog_content = "Por supuesto. ¡Estoy extremadamente seguro del proyecto!",
  ui_story_5058_50580501_62_dialog_content = "Hola, veo mariposas.",
  ui_story_5058_50580501_63_dialog_content = "¡Sí! ¡Veo varios allá también!",
  ui_story_5058_50580501_64_dialog_content = "Me pregunto si la Diosa Denuo está entre ellas.",
  ui_story_5058_50580501_65_dialog_content = "Señorita Lorelei, ¿p-puedo ir a buscar a la Diosa Denuo?",
  ui_story_5058_50580501_66_dialog_content = "¿Incluso tienes una red lista para usar, Bopper?!",
  ui_story_5058_50580501_67_dialog_content = "Mucha gente me preguntó si es cierto que la Diosa Denuo está en el valle... ¡Me encantaría demostrárselo!",
  ui_story_5058_50580501_68_dialog_content = "Está bien, pero si te encuentras con ellos, ten cuidado de no hacerles daño.",
  ui_story_5058_50580501_69_dialog_content = "¿Por qué no miramos también? ¡Hay fuerza en números!",
  ui_story_5058_50580501_70_dialog_content = "¡Incluso podemos dividirnos para cubrir más terreno!",
  ui_story_5058_50580501_71_dialog_content = "Lo estás convirtiendo en otra competencia, ¿verdad?",
  ui_story_5058_50580501_72_dialog_content = "Jeje, no me mires así... ¿Por qué no me uno al equipo con Carleen esta vez entonces?",
  ui_story_5058_50580501_73_dialog_content = "¡Vamos, vámonos! ¡Veamos quién encuentra a la Diosa primero!",
  ui_story_5058_50580501_74_dialog_content = "Bostezo-",
  ui_story_5058_50580501_75_dialog_content = "Niños... Un día bonito como este es perfecto para una siesta.",
  ui_story_5058_50580501_76_dialog_content = "Zzzz—Zzzz—",
  ui_story_5058_50580501_77_dialog_content = "Ven aquí, Carleen, ¡lo encontré!",
  ui_story_5058_50580501_78_dialog_content = "¿Tan rápido?",
  ui_story_5058_50580501_79_dialog_content = "¡Ta-da!",
  ui_story_5058_50580501_80_dialog_content = "¿Ah? ¿Qué es eso?",
  ui_story_5058_50580501_81_dialog_content = "¡Nunca había visto una polilla tan grande antes!",
  ui_story_5058_50580501_82_dialog_content = "¡¡¡Mantente alejado de mí!!!",
  ui_story_5058_50580501_83_dialog_content = "¿Han visto a la Diosa Denuo, pequeñas mariposas?",
  ui_story_5058_50580501_84_dialog_content = "Estás revoloteando en sentido horario a mi alrededor... ¿Qué estás tratando de decir?",
  ui_story_5058_50580501_85_dialog_content = "Hmm, supongo que solo puedo leer la mente de Lepidoz...",
  ui_story_5058_50580501_86_dialog_content = "¿Qué haces aquí, PlayerName?",
  ui_story_5058_50580501_87_dialog_content = "Solo estoy esperando el momento adecuado...",
  ui_story_5058_50580501_88_dialog_content = "No te muevas... Hay una mariposa en tu cabeza.",
  ui_story_5058_50580501_89_dialog_content = "Cena, ¡ven a tomarnos fotos!",
  ui_story_5058_50580501_90_dialog_content = "Bostezo-",
  ui_story_5058_50580501_91_dialog_content = "Ya voy...",
  ui_story_5058_50580501_92_dialog_content = "<color=#e8d9bb>¡Chasquido!</color>",
  ui_story_5058_50580501_93_dialog_content = "Bueno, todo ese esfuerzo y aún no hay Diosa Denuo.",
  ui_story_5058_50580501_94_dialog_content = "La verdad, también he tenido dudas sobre la existencia de la Diosa Denuo.",
  ui_story_5058_50580501_95_dialog_content = "Tampoco estoy seguro. ¿No dijiste que viste uno antes, Cena?",
  ui_story_5058_50580501_96_dialog_content = "¿Dije eso? No lo recuerdo muy bien...",
  ui_story_5058_50580501_97_dialog_content = "Algunos afirmaron haber visto a la Diosa Denuo, pero la Diosa es en realidad un mito más que cualquier otra cosa.",
  ui_story_5058_50580501_98_dialog_content = "Muchos inversores invirtieron en el complejo turístico simplemente porque escucharon que está en el valle.",
  ui_story_5058_50580501_99_dialog_content = "Querían que fuera un truco para atraer turistas... No pude oponerme a la decisión de la Junta.",
  ui_story_5058_50580501_100_dialog_content = "Pero cuando vi el amor y el soporte abrumador de los clientes por las pegatinas de la Diosa Denuo y cómo incluso están dispuestos a pagar mucho dinero solo para ver una aquí, me hizo entrar en pánico un poquito.",
  ui_story_5058_50580501_101_dialog_content = "Porque desde la construcción hasta ahora, ninguno de nosotros ha visto uno aquí.",
  ui_story_5058_50580501_102_dialog_content = "Si la Diosa Denuo no es real, es publicidad falsa y no quiero mentir a los invitados...",
  ui_story_5058_50580501_103_dialog_content = "Pero si es real, ¿no atraería lo que estoy haciendo a aquellos que podrían dañar a la Diosa...",
  ui_story_5058_50580501_104_dialog_content = "No tenía la intención de ocultarlo. Simplemente no pude encontrar una solución a este problema complicado... ¡Lo siento!",
  ui_story_5058_50580501_105_dialog_content = "Deberíamos ser nosotros los que nos disculpemos por lo imprudentes y groseros que fuimos.",
  ui_story_5058_50580501_106_dialog_content = "Está bien. Si se pudiera encontrar a la Diosa, tal vez podamos proliferarlas.",
  ui_story_5058_50580501_107_dialog_content = "Además, sé que nunca dañarías a las mariposas. Y también me divertí.",
  ui_story_5058_50580501_108_dialog_content = "Son las otras personas de las que estoy nervioso...",
  ui_story_5058_50580501_109_dialog_content = "Puedo decir que no te rindes fácilmente, Lorelei. Podemos resolverlo juntos.",
  ui_story_5058_50580501_110_dialog_content = "¡Sí! He encontrado a un experto en animales que podría ofrecer sugerencias útiles.",
  ui_story_5058_50580501_111_dialog_content = "(¿Experto en animales? ¿No podría ser Vic, verdad?)",
  ui_story_5058_50580501_112_dialog_content = "Todavía espero que tales mariposas hermosas sean reales.",
  ui_story_5058_50580501_113_dialog_content = "Las mariposas en las pegatinas supuestamente son jóvenes.",
  ui_story_5058_50580501_114_dialog_content = "Se rumorea que las diosas adultas son enormes, esbeltas y blancas en todo su ser.",
  ui_story_5058_50580501_115_dialog_content = "¿Qué tan enorme es enorme? ¿El tamaño del lagarto, quizás?",
  ui_story_5058_50580501_116_dialog_content = "Chicos, miren ese arbusto por ahí... ¿Es esa la Diosa Denuo?",
  ui_story_5058_50580501_117_dialog_content = "¿Dónde?",
  ui_story_5058_50580501_118_dialog_content = "Allí, completamente blanco...",
  ui_story_5058_50580501_119_dialog_content = "¡¡¡Rugido!!!",
  ui_story_5058_50580501_120_dialog_content = "¿Eclipsites?",
  ui_story_5058_50580501_121_dialog_content = "¿Cómo puede haber Eclipsitas en el Valle de Denuo?",
  ui_story_5058_50580502_1_dialog_content = "Oh no, me he separado...",
  ui_story_5058_50580502_2_dialog_content = "Hiss-",
  ui_story_5058_50580502_3_dialog_content = "¿Qué es ese ruido?",
  ui_story_5058_50580502_4_dialog_content = "Silbido-!",
  ui_story_5058_50580502_5_dialog_content = "PlayerName... ¿PlayerName?",
  ui_story_5058_50580502_6_dialog_content = "¿Alguien... está llamando mi nombre?",
  ui_story_5058_50580502_7_dialog_content = "¡Te encontré! ¡Pequeño travieso! Es hora de volver a casa con mamá para cenar. Sabes que la gente tiene que comer para crecer, ¿verdad?",
  ui_story_5058_50580502_8_dialog_content = "M-Mamá...",
  ui_story_5058_50580502_9_dialog_content = "La sensación... Tan cómoda, acogedora, familiar...",
  ui_story_5058_50580502_10_dialog_content = "Ven con mamá. Vamos a casa.",
  ui_story_5058_50580502_11_dialog_content = "Seguro...",
  ui_story_5058_50580502_12_dialog_content = "¡... no!",
  ui_story_5058_50580502_13_dialog_content = "Pensé que estaba en el complejo turístico... ¿Y nos encontramos con Eclipsites, incluso?",
  ui_story_5058_50580502_14_dialog_content = "¿Estoy soñando? ¿O teniendo una visión?",
  ui_story_5058_50580502_15_dialog_content = "¿Qué pasa, PlayerName? ¿Por qué no vienes?",
  ui_story_5058_50580502_16_dialog_content = "Realmente quiero seguir soñando...",
  ui_story_5058_50580502_17_dialog_content = "Pero ratas, ¿cómo es que no puedo despertar?",
  ui_story_5058_50580502_18_dialog_content = "Si esto continúa, solo puedo...",
  ui_story_5058_50580502_19_option_content = "¡Potencia de fuerza!",
  ui_story_5058_50580502_20_dialog_content = "Hiss-",
  ui_story_5058_50580502_21_dialog_content = "¿Estoy despierto ahora?",
  ui_story_5058_50580502_22_dialog_content = "...",
  ui_story_5058_50580502_23_dialog_content = "¿Quién eres?",
  ui_story_5058_50580502_24_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5058_50580502_25_dialog_content = "El pueblo... arenoso y polvoriento... ¿Es una colonia Eclipsita?",
  ui_story_5058_50580502_26_dialog_content = "¿Estoy en el sueño de alguien más?",
  ui_story_5058_50580502_27_dialog_content = "<color=#e8d9bb>¡Guau! ¡Guau!</color>",
  ui_story_5058_50580502_28_dialog_content = "La tormenta de arena está... empeorando...",
  ui_story_5058_50580502_29_dialog_content = "Soy...",
  ui_story_5058_50580502_30_dialog_content = "... sofocante...",
  ui_story_5058_50580601_1_dialog_content = "¡PlayerName!",
  ui_story_5058_50580601_2_dialog_content = "¿Mamá...?",
  ui_story_5058_50580601_3_dialog_content = "¡Despierta, PlayerName!",
  ui_story_5058_50580601_4_dialog_content = "Vice... Carleen... ¿Chicos?",
  ui_story_5058_50580601_5_dialog_content = "¡Bien, estás despierto! Lo siento por dejarte detrás. No nos dimos cuenta hasta que estábamos lejos.",
  ui_story_5058_50580601_6_dialog_content = "Lo siento, probablemente estoy exhausto de todas las actividades de hoy...",
  ui_story_5058_50580601_7_dialog_content = "Me sentí somnoliento mientras corría y no pude evitar quedarme dormido, incluso tuve sueños extraños de los que simplemente no podía despertar.",
  ui_story_5058_50580601_8_dialog_content = "Me asustaste...",
  ui_story_5058_50580601_9_dialog_content = "Me alegra ver que PlayerName está bien. Sería una pérdida para Astra que no podría recuperarse incluso si vendiera todos mis activos.",
  ui_story_5058_50580601_10_dialog_content = "¿Pero cómo es que hay Eclipsitas aquí?",
  ui_story_5058_50580601_11_dialog_content = "Tampoco estoy seguro... El cañón es lo suficientemente conflictivo como para que se aventuren en él, normalmente.",
  ui_story_5058_50580601_12_dialog_content = "Solo contraté un pequeño equipo de seguridad para patrullar los perímetros exteriores.",
  ui_story_5058_50580601_13_dialog_content = "Pensé que eso sería suficiente para mantenerte a salvo... ¡Lo siento mucho!",
  ui_story_5058_50580601_14_dialog_content = "Cena, tenemos que conseguir armas anti-Eclipsite rápido cuando regresemos.",
  ui_story_5058_50580601_15_dialog_content = "Entiendo. Entonces, ¿qué hacemos ahora...?",
  ui_story_5058_50580601_16_dialog_content = "Volvamos al parque. Necesitamos un plan para esto.",
  ui_story_5058_50580601_17_dialog_content = "¡Graagh!",
  ui_story_5058_50580601_18_dialog_content = "¡Ay, es tan aterrador!",
  ui_story_5058_50580601_19_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5058_50580601_20_dialog_content = "¡Un disparo, un muerto!",
  ui_story_5058_50580601_21_dialog_content = "¡Eso es más como! El espectáculo está comenzando de una manera muy auténtica y emocionante.",
  ui_story_5058_50580601_22_dialog_content = "¿Ya comenzó el espectáculo?",
  ui_story_5058_50580601_23_dialog_content = "¿No has escuchado una palabra de lo que dije, Maestro? No veo ninguna bestia maravillosa aquí... ¿Qué tan legítima es esta tarea que tienes?",
  ui_story_5058_50580601_24_dialog_content = "Ay, no importa. No voy a perder más de mi tiempo. ¡Voy a regresar a ver el espectáculo!",
  ui_story_5058_50580601_25_dialog_content = "Es bueno ser joven... No como el viejo conjunto de huesos que tengo. Es mejor para mí dormitar usando una pequeña bola de pelo como almohada.",
  ui_story_5058_50580601_26_dialog_content = "¡Gahhhh!",
  ui_story_5058_50580601_27_dialog_content = "Vaya, los Eclipsites se ven realmente realistas esta vez, incluso las muelas parecen auténticas...",
  ui_story_5058_50580601_28_dialog_content = "¡Rugido!",
  ui_story_5058_50580601_29_dialog_content = "¡No, estúpido maestro, eso es un eclipse real!",
  ui_story_5058_50580601_30_dialog_content = "Los Eclipsites invadieron el parque, de verdad...",
  ui_story_5058_50580601_31_dialog_content = "Cena, evacuar a los invitados. Bopper, escoltar a todos al hotel. Tengo que conseguir seguridad para deshacerme de los Eclipsites.",
  ui_story_5058_50580601_32_dialog_content = "No hay problema, jefe, aunque probablemente la Junta será más difícil de tratar que los Eclipsites.",
  ui_story_5058_50580601_33_dialog_content = "...",
  ui_story_5058_50580601_34_dialog_content = "¿Quién prometió que nunca aparecería Eclipsite aquí?",
  ui_story_5058_50580601_35_dialog_content = "¡Nos debías una explicación, Lorelei!",
  ui_story_5058_50580601_36_dialog_content = "Ahora no es el momento de discutir ese tema.",
  ui_story_5058_50580601_37_dialog_content = "Estás aquí, Lady Carleen?",
  ui_story_5058_50580601_38_dialog_content = "Solo ayudo a mi papá con su inversión en mis días libres, ¡nada más!",
  ui_story_5058_50580601_39_dialog_content = "Aclaración innecesaria.",
  ui_story_5058_50580601_40_dialog_content = "Los Eclipsites son realmente mi culpa y negligencia, Directores, pero su seguridad es la preocupación principal...",
  ui_story_5058_50580601_41_dialog_content = "Por favor, siga al personal de vuelta al hotel para refugiarse. ¡Yo me encargaré de todo y lo explicaré luego!",
  ui_story_5058_50580601_42_dialog_content = "Bopper, dejaré a PlayerName y amigos contigo.",
  ui_story_5058_50580601_43_dialog_content = "¡Está bien!",
  ui_story_5058_50580601_44_dialog_content = "Pero no podemos ni debemos dejarte enfrentar todo esto solo, Lorelei...",
  ui_story_5058_50580601_45_dialog_content = "Sí. Será mucho más rápido para nosotros eliminar a los Eclipsites juntos.",
  ui_story_5058_50580601_46_dialog_content = "¡Así es, todos somos experimentados, tú sabes!",
  ui_story_5058_50580601_47_dialog_content = "Esto es inesperado. No pensé que tú lo harías...",
  ui_story_5058_50580601_48_dialog_content = "¡Oye, son Vic y Fia? ¡También están peleando!",
  ui_story_5058_50580601_49_dialog_content = "¡Eliminemos a los Eclipsites que nos rodean y luego unámonos a ellos!",
  ui_story_5058_50580601_50_dialog_content = "¡Sí!",
  ui_story_5058_50580601_51_dialog_content = "Veo que me veo obligado a luchar junto a ustedes, campesinos, por el bien de la Lady Carleen.",
  ui_story_5058_50580702_1_dialog_content = "Todos los Eclipsites en las inmediaciones han sido tratados. Gracias a todos por su ayuda.",
  ui_story_5058_50580702_2_dialog_content = "Pero debo insistir en que te refugies en el hotel y déjame encargarme del resto.",
  ui_story_5058_50580702_3_dialog_content = "Siempre dices \"Déjame encargarme del resto\", pero nada es tan simple como eso.",
  ui_story_5058_50580702_4_dialog_content = "Shashona...",
  ui_story_5058_50580702_5_dialog_content = "No quería que vinieras aquí y construyeras un complejo turístico. ¡Seguro que algo malo está pasando!",
  ui_story_5058_50580702_6_dialog_content = "Tú también viste las caras de los directores. Ellos no creen que puedas lograrlo en absoluto.",
  ui_story_5058_50580702_7_dialog_content = "Haz lo que digo y cierra el parque ahora.",
  ui_story_5058_50580702_8_dialog_content = "Mamá, ¿cómo puedes ser tan irresponsable ahora?",
  ui_story_5058_50580702_9_dialog_content = "No puedo dejar a mi personal e invitados en el aire, ni puedo traicionar a los inversores.",
  ui_story_5058_50580702_10_dialog_content = "¿Sabes lo que pasé para construir este complejo turístico?",
  ui_story_5058_50580702_11_dialog_content = "¿Quieres que lo cierre justo cuando está a punto de lanzarse?",
  ui_story_5058_50580702_12_dialog_content = "Sé que hiciste muchos sacrificios, ¡por eso siento que esto no vale la pena!",
  ui_story_5058_50580702_13_dialog_content = "La familia te ayudaría con cualquier cosa que quisieras hacer, pero insististe en ir solo...",
  ui_story_5058_50580702_14_dialog_content = "No te preocupes por mí, mamá. Vuelve al hotel y yo me encargo de todo.",
  ui_story_5058_50580702_15_dialog_content = "Pero sin importar qué, no voy a cerrar el parque.",
  ui_story_5058_50580702_16_dialog_content = "Escúchame, Laurie...",
  ui_story_5058_50580702_17_dialog_content = "Sra. Shashona!",
  ui_story_5058_50580702_18_dialog_content = "Cena está aquí. Él puede llevarte. Todavía tengo muchos asuntos pendientes.",
  ui_story_5058_50580702_19_dialog_content = "Ha pasado mucho tiempo, Sra. Shashona.",
  ui_story_5058_50580702_20_dialog_content = "...",
  ui_story_5058_50580702_21_dialog_content = "¡Esto es una farsa!",
  ui_story_5058_50580702_22_dialog_content = "El hotel está por ese camino...",
  ui_story_5058_50580702_23_dialog_content = "Bopper, me preocupa que algunos invitados aún puedan estar en el parque. Enviaré seguridad para revisar de nuevo.",
  ui_story_5058_50580702_24_dialog_content = "Tú y el personal del hotel verifican con los huéspedes para satisfacer sus necesidades.",
  ui_story_5058_50580702_25_dialog_content = "Te veré después de revisar las medidas de emergencia del hotel.",
  ui_story_5058_50580702_26_dialog_content = "¿Eh? Pero eso no está en mi descripción de trabajo...",
  ui_story_5058_50580702_27_dialog_content = "PlayerName, Vice, Carleen, ustedes deben regresar a sus habitaciones. Nos reuniremos de nuevo después de que las cosas se calmen.",
  ui_story_5058_50580702_28_dialog_content = "Le faltan personas ahora mismo, señorita Lorelei. Permítanos ayudar.",
  ui_story_5058_50580702_29_dialog_content = "¡Yo, por mi parte, no quiero ser tratado como un turista común! ¡Juntos perseguimos mariposas y luchamos contra Eclipsites, y eso nos hace amigos!",
  ui_story_5058_50580702_30_dialog_content = "Gracias, pero debo hacer esto por mi cuenta. Viste lo que pasó...",
  ui_story_5058_50580702_31_dialog_content = "¿Porque tu mamá se opuso? De hecho, entiendo cuánto quieres hacer esto por tu cuenta.",
  ui_story_5058_50580702_32_dialog_content = "¿Fui demasiado duro con mi mamá?",
  ui_story_5058_50580702_33_dialog_content = "¿Hay algo en tu mente, Lorelei? Escucharemos si no te importa...",
  ui_story_5058_50580702_34_dialog_content = "Sí, no lo guardes dentro de ti.",
  ui_story_5058_50580702_35_dialog_content = "Bueno, no quería actuar de esa manera, pero por alguna razón, nunca estuve en buenos términos con mi mamá desde que me independicé.",
  ui_story_5058_50580702_36_dialog_content = "Sé que ella me ama mucho. Ella tolera y acepta todo lo que hago, excepto comenzar mi propio negocio...",
  ui_story_5058_50580702_37_dialog_content = "Y eso es exactamente por qué tengo que demostrar que puedo manejar las cosas por mí mismo.",
  ui_story_5058_50580702_38_dialog_content = "Cuanto más intenta detenerme, más lucho para regresar...",
  ui_story_5058_50580702_39_dialog_content = "Probablemente sea infantil, pero simplemente no puedo controlarme...",
  ui_story_5058_50580702_40_dialog_content = "Es difícil para una persona introspectar como tú lo acabas de hacer. Entiendo a tu mamá, sin embargo, ella teme que te lastimes...",
  ui_story_5058_50580702_41_dialog_content = "Sí, ella no te culpa ni nada. Solo está preocupada por ti.",
  ui_story_5058_50580702_42_dialog_content = "EveTodos pierden el control a veces, pero un poco de comprensión mutua será suficiente.",
  ui_story_5058_50580702_43_dialog_content = "Espero que también sea así.",
  ui_story_5058_50580702_44_dialog_content = "Pero para evitar que ella intente detenerme de hacer algo en el futuro, debo superar este peligro en curso.",
  ui_story_5058_50580702_45_dialog_content = "Solo discúlpate con ella después de que pase.",
  ui_story_5058_50580702_46_dialog_content = "¡Correcto! Sí siento un peso menos en mis hombros.",
  ui_story_5058_50580702_47_dialog_content = "¡Entonces permítenos ser parte de tu plan de gestión de crisis!",
  ui_story_5058_50580702_48_dialog_content = "¡Lo superaremos juntos, y luego ella te verá bajo una nueva luz con seguridad!",
  ui_story_5058_50580702_49_dialog_content = "No olvides a tus trabajadores con llave Rediesel, tampoco.",
  ui_story_5058_50580702_50_dialog_content = "Gracias.",
  ui_story_5058_50580702_51_dialog_content = "Entonces, ¿cuáles son tus instrucciones, jefe?",
  ui_story_5058_50580702_52_dialog_content = "Primero, debemos mantener a los invitados tranquilos y asegurar su fuera de peligro.",
  ui_story_5058_50580702_53_dialog_content = "Una vez que hayamos asegurado el perímetro del hotel, busquen todas las brechas y tomen medidas adecuadas para solucionarlas.",
  ui_story_5058_50580702_54_dialog_content = "Ahí está el trabajo para tu personal de Rediesel Wrench, Bopper.",
  ui_story_5058_50580702_55_dialog_content = "Está bien siempre y cuando les paguen.",
  ui_story_5058_50580801_1_dialog_content = "No tenga tanta prisa, Sra. Shashona...",
  ui_story_5058_50580801_2_dialog_content = "Vaya, ¿por qué no nos tranquilizamos y guardamos esa pistola?",
  ui_story_5058_50580801_3_dialog_content = "No hay nada de qué hablar con un charlatán como tú.",
  ui_story_5058_50580801_4_dialog_content = "¿Por qué regresaste a Lorelei esta vez?",
  ui_story_5058_50580801_5_dialog_content = "Lo entendiste todo mal, es solo una coincidencia...",
  ui_story_5058_50580801_6_dialog_content = "¿Coincidencia? Supongo que descubriste que Lorelei es una chica rica ahora y querías estafarla?",
  ui_story_5058_50580801_7_dialog_content = "Tú eras solo un servidor que mi esposo y yo contratamos en uno de nuestros viajes.",
  ui_story_5058_50580801_8_dialog_content = "Un día, me trajiste a Lorelei y pediste un adelanto para llevarla a ver a un médico.",
  ui_story_5058_50580801_9_dialog_content = "No podía soportar verla llorar, así que decidí acogerla.",
  ui_story_5058_50580801_10_dialog_content = "Ya sea que realmente quisieras ayudarla o no, ya te pagué una buena suma.",
  ui_story_5058_50580801_11_dialog_content = "Y también me prometiste que nunca más estarías cerca de ella.",
  ui_story_5058_50580801_12_dialog_content = "Solo para que tú aparezcas más de diez años después y luego ella arme un escándalo sobre lanzar un complejo turístico en el Valle de Denuo de inmediato. ¿Llamas eso una coincidencia?",
  ui_story_5058_50580801_13_dialog_content = "Escúchame, Sra. Shashona, realmente conocí a Lorelei por pura casualidad.",
  ui_story_5058_50580801_14_dialog_content = "Y decidí ayudar porque admiraba su idea de hacer verde el valle.",
  ui_story_5058_50580801_15_dialog_content = "Tú también sabes muy bien que trabajo en empleos ocasionales y necesito ganarme la vida.",
  ui_story_5058_50580801_16_dialog_content = "Entonces, ¿qué hiciste además de recibir pago? Este valle es completamente inseguro.",
  ui_story_5058_50580801_17_dialog_content = "No me di cuenta hasta que vi las pegatinas de mariposas hoy... Este es en realidad el lugar de donde tú y Lorelei son, ¿no es así?",
  ui_story_5058_50580801_18_dialog_content = "El mismo pueblo maldito por la Diosa Denuo, como tú explicaste en aquel momento...",
  ui_story_5058_50580801_19_dialog_content = "El alboroto sobre la Diosa en todo el parque me da la sensación de que algo está a punto de llevarse Lorelei...",
  ui_story_5058_50580801_20_dialog_content = "\"Maldito por la Diosa Denuo\"... ¿Cómo puedes decir eso tan ligeramente?",
  ui_story_5058_50580801_21_dialog_content = "Nunca quise mencionar el pueblo.",
  ui_story_5058_50580801_22_dialog_content = "Even cuando vuelvo a pisar esta tierra de nuevo, su pasada destrucción aún me persigue...",
  ui_story_5058_50580801_23_dialog_content = "Pero cuando vi cuán decidido y dedicado estaba Lorelei en cambiar gradualmente el valle, finalmente también vi esperanza...",
  ui_story_5058_50580801_24_dialog_content = "Entonces admites que estás ayudando a Lorelei a reconstruir tu hogar?",
  ui_story_5058_50580801_25_dialog_content = "¿Sabe ella que tú fuiste quien la salvó?",
  ui_story_5058_50580801_26_dialog_content = "...",
  ui_story_5058_50580801_27_dialog_content = "Y ese es el plan integral para el complejo turístico y la ecologización de todo el cañón. ¿Qué piensas?",
  ui_story_5058_50580801_28_dialog_content = "Eso no es un plan, mujer joven.",
  ui_story_5058_50580801_29_dialog_content = "Restaurar la naturaleza, inmortalizar la experiencia de ir al parque con los padres... Simplemente es una pérdida de mi tiempo.",
  ui_story_5058_50580801_30_dialog_content = "Escúchame, Jefe Sinsa, ¡prometo el mejor pago para todos los que trabajen en el proyecto!",
  ui_story_5058_50580801_31_dialog_content = "Como muchos expertos que tiene Rediesel Wrench, necesitan una etapa para mostrar sus habilidades...",
  ui_story_5058_50580801_32_dialog_content = "No hay nada que discutir. ¿Nosotros trabajando para alguien más? De ninguna manera...",
  ui_story_5058_50580801_33_dialog_content = "Estoy interesado. Mayquizás pueda ayudar.",
  ui_story_5058_50580801_34_dialog_content = "Oye, ¿no eres Cena?",
  ui_story_5058_50580801_35_dialog_content = "¿Todavía me recuerdas?",
  ui_story_5058_50580801_36_dialog_content = "¡No me digas que son hermanos perdidos hace mucho tiempo o algo así!",
  ui_story_5058_50580801_37_dialog_content = "Por supuesto que te recuerdo. ¿Cómo puedo olvidar a la persona que me salvó?",
  ui_story_5058_50580801_38_dialog_content = "¿Dónde fuiste? Seguía esperando poder verte de nuevo.",
  ui_story_5058_50580801_39_dialog_content = "...",
  ui_story_5058_50580801_40_dialog_content = "Entiendo. Probablemente mamá no quería que estuvieras cerca de mí.",
  ui_story_5058_50580801_41_dialog_content = "¡Pero es tan bueno verte de nuevo!",
  ui_story_5058_50580801_42_dialog_content = "Ejem... Lo siento, casi olvido que vine aquí por negocios.",
  ui_story_5058_50580801_43_dialog_content = "Comencemos de nuevo. Mi nombre es Lorelei Cardogon. ¡Mucho gusto!",
  ui_story_5058_50580801_44_dialog_content = "Oh, y no le digas a mamá que aún te recuerdo.",
  ui_story_5058_50580801_45_dialog_content = "Seguro. Buena suerte con el acuerdo.",
  ui_story_5058_50580801_46_dialog_content = "Espera, mencionaste que quieres ayudar, pero soy muy estricto cuando se trata de contratar.",
  ui_story_5058_50580801_47_dialog_content = "¡Tendrás que pasar una evaluación antes de poder comenzar!",
  ui_story_5058_50580801_48_dialog_content = "Oye, ¿así tratas a alguien que te salvó?",
  ui_story_5058_50580801_49_dialog_content = "Hmm, resulta que eres interesante, Lorelei. Maytal vez pueda diseñar algunas atracciones para ti también.",
  ui_story_5058_50580801_50_dialog_content = "Eso será genial, Jefe Sinsa! Sabía que el Desierto de Rediesel es en realidad un lugar genial.",
  ui_story_5058_50580801_51_dialog_content = "No te preocupes, no dije nada. Para ella, solo soy un empleado.",
  ui_story_5058_50580801_52_dialog_content = "Y por favor relájate, Lorelei es un gran niño. Te preocupas por cosas que no sucederán.",
  ui_story_5058_50580801_53_dialog_content = "¿No sucederá? Entonces, ¿qué eran esos Eclipsites?",
  ui_story_5058_50580801_54_dialog_content = "Vaya, el estrés que siento... ¿No crees que ella pueda manejarlo? O...",
  ui_story_5058_50580801_55_dialog_content = "¿Tienes miedo de que si ella resuelve esta crisis, se pondría de pie lo suficiente como para... dejarte?",
  ui_story_5058_50580801_56_dialog_content = "Hmm, incluso me pregunto si tú deliberadamente trajiste a los Eclipsites...",
  ui_story_5058_50580801_57_dialog_content = "¿Y dejar que lastimen a mi hijo? ¿Eso es algo que una madre haría?",
  ui_story_5058_50580801_58_dialog_content = "Siempre la he tratado como si fuera mi propia hija. ¿Por qué no querría verla triunfar?",
  ui_story_5058_50580801_59_dialog_content = "Mantenerse en pie... Dirigir su propia vida...",
  ui_story_5058_50580801_60_dialog_content = "Sé que eso va a pasar tarde o temprano.",
  ui_story_5058_50580801_61_dialog_content = "Todo lo que puedo esperar es que sea más tarde para poder allanarle mejor el camino a ella...",
  ui_story_5058_50580801_62_dialog_content = "Je, tan comprensivo pero tan difícil de dejarlo ir!",
  ui_story_5058_50580801_63_dialog_content = "<size=45>Graaagh!</size>",
  ui_story_5058_50580801_64_dialog_content = "Hablaremos de eso más tarde. Terminemos primero con los Eclipsites, Sra. Shashona.",
  ui_story_5058_50580802_1_dialog_content = "Listo.",
  ui_story_5058_50580802_2_dialog_content = "Realmente eres un tirador certero, Sra. Shashona.",
  ui_story_5058_50580802_3_dialog_content = "Espera... Esta sensación... Es la misma que antes...",
  ui_story_5058_50580802_4_dialog_content = "Podría ser...",
  ui_story_5058_50580802_5_dialog_content = "¿Qué estás diciendo, Cena?",
  ui_story_5058_50580802_6_dialog_content = "Nah, no puede ser, está todo completado...",
  ui_story_5058_50580802_7_dialog_content = "Lo siento, Sra. Shashona, no puedo acompañarte a regresar. Algo acaba de surgir.",
  ui_story_5058_50580802_8_dialog_content = "¿A dónde vas?",
  ui_story_5058_50580802_9_dialog_content = "Sabes que el valle y Lorelei están en peligro, ¿cierto?",
  ui_story_5058_50580802_10_dialog_content = "<size=45>¡Oye...!</size>",
  ui_story_5058_50580901_1_dialog_content = "¡Has vuelto, Lorelei! ¿Cómo se ve todo afuera?",
  ui_story_5058_50580901_2_dialog_content = "No hay señales de Eclipsitas por ahora, pero aún no tenemos idea de por qué se entrometerían de repente...",
  ui_story_5058_50580901_3_dialog_content = "¿Qué pasa con los invitados?",
  ui_story_5058_50580901_4_dialog_content = "Ayudamos a todos a sus habitaciones, pero el gerente y Shashona no se ven por ninguna parte...",
  ui_story_5058_50580901_5_dialog_content = "Cena ¿y mi mamá? ¿Revisaste cada rincón del hotel?",
  ui_story_5058_50580901_6_dialog_content = "Sí, en todas partes.",
  ui_story_5058_50580901_7_dialog_content = "Gracias por informarme, Bopper. Por favor, dile al equipo de seguridad que establezca defensas alrededor del hotel.",
  ui_story_5058_50580901_8_dialog_content = "Además, recuerda al personal que prepare y entregue las comidas a los invitados a tiempo, ni un segundo tarde...",
  ui_story_5058_50580901_9_dialog_content = "¡Rugido!",
  ui_story_5058_50580901_10_dialog_content = "¿Qué?",
  ui_story_5058_50580901_11_dialog_content = "¡Flor de hielo!",
  ui_story_5058_50580901_12_dialog_content = "¡Vaya, qué reflejos de relámpago, Carleen! ¡Mataste al Eclipsite antes de que yo supiera que estaba allí!",
  ui_story_5058_50580901_13_dialog_content = "Pero, ¿cómo llegaron...",
  ui_story_5058_50580901_14_dialog_content = "Dentro... del hotel...",
  ui_story_5058_50580901_15_dialog_content = "Lorelei...? Tú...",
  ui_story_5058_50580901_16_dialog_content = "Mis ojos... no puedo mantenerlos abiertos...",
  ui_story_5058_50580901_17_dialog_content = "PlayerName...",
  ui_story_5058_50580901_18_dialog_content = "...",
  ui_story_5058_50580901_19_dialog_content = "Vice... Carleen...?!",
  ui_story_5058_50580901_20_dialog_content = "¿Qué... está pasando...",
  ui_story_5058_50580901_21_dialog_content = "PlayerName... ¿PlayerName?",
  ui_story_5058_50580901_22_dialog_content = "¿Ah?",
  ui_story_5058_50580901_23_dialog_content = "¡Te encontré! ¡Pequeño travieso! Es hora de volver a casa con mamá para cenar. Sabes que la gente tiene que comer para crecer, ¿verdad?",
  ui_story_5058_50580901_24_dialog_content = "¿Otro sueño?",
  ui_story_5058_50580901_25_dialog_content = "¿De nuevo? Pero esta vez...",
  ui_story_5058_50580901_26_option_content = "¡Vamos, despierta!",
  ui_story_5058_50580901_27_dialog_content = "Uf... ¿Qué acaba de pasar? Se sintió exactamente igual que cuando me desmayé en el valle.",
  ui_story_5058_50580901_28_dialog_content = "EveTodos están afuera...",
  ui_story_5058_50580901_29_dialog_content = "Lorelei? Lorelei! ¡Despierta!",
  ui_story_5058_50580901_30_dialog_content = "Mamá... mamá...",
  ui_story_5058_50580901_31_dialog_content = "¡Vice! ¡Carleen!",
  ui_story_5058_50580901_32_dialog_content = "Tengo que cocinar... hacer nuevos platos...",
  ui_story_5058_50580901_33_dialog_content = "...",
  ui_story_5058_50580901_34_dialog_content = "¿Todos están en trance? Oye, ¿qué es eso parpadeando en el aire?",
  ui_story_5058_50580901_35_dialog_content = "¡Está en todas partes, por todo el hotel! ¿Es lo que dejó a la gente inconsciente?",
  ui_story_5058_50580901_36_dialog_content = "¿Qué voy a hacer? Puedo despertarlos telepáticamente... No, abrir la ventana y dejar entrar el aire fresco.",
  ui_story_5058_50580901_37_dialog_content = "Pero entonces, ¿no podrán entrar los Eclipsitas que están afuera?",
  ui_story_5058_50580901_38_dialog_content = "Hmm, ¿no mencionó Lorelei un sistema de ventilación? ¡Vamos a encenderlo!",
  ui_story_5058_50580901_39_dialog_content = "El problema es que no sé dónde está el interruptor.",
  ui_story_5058_50580901_40_dialog_content = "Lorelei lo sabría con seguridad! Sí, ¡la despertaré primero!",
  ui_story_5058_50580901_41_option_content = "¡Potencia de fuerza!",
  ui_story_5058_50580901_42_dialog_content = "¿Estás dormido, Lorelei?",
  ui_story_5058_50580901_43_dialog_content = "¡No, solo estoy escuchando a mamá contándome una historia con los ojos cerrados!",
  ui_story_5058_50580901_44_dialog_content = "(Esta debe ser la memoria de Lorelei.)",
  ui_story_5058_50580901_45_dialog_content = "(Es esa niña Lorelei? Pero su madre no parece Shashona!)",
  ui_story_5058_50580901_46_dialog_content = "(¡Y ese joven de allí es la figura que vi cuando me desmayé en el valle!)",
  ui_story_5058_50580901_47_dialog_content = "La leyenda cuenta que el Valle de Denuo está libre de Eclipsitas porque estamos bajo la protección de la <color=#FFB400>Diosa Denuo</color>.",
  ui_story_5058_50580901_48_dialog_content = "¿Mariposas? ¿Te refieres a las que están a nuestro alrededor?",
  ui_story_5058_50580901_49_dialog_content = "Las Diosas Denuo no son mariposas comunes. Tienen alas tan brillantes como diamantes.",
  ui_story_5058_50580901_50_dialog_content = "EveTodos los que vean a una Diosa recibirán la bendición de una revelación y alegría sin igual.",
  ui_story_5058_50580901_51_dialog_content = "¿En serio? ¿Cuándo puedo ver uno?",
  ui_story_5058_50580901_52_dialog_content = "Oh niño, no es fácil ver a una Diosa.",
  ui_story_5058_50580901_53_dialog_content = "Se dice que viven en el Valle de Denuo, pero apenas se muestran a nadie.",
  ui_story_5058_50580901_54_dialog_content = "Creo que vi a una joven Diosa Denuo hace unos días.",
  ui_story_5058_50580901_55_dialog_content = "No podía apartar mis ojos de ese brillo brillante de sus alas... ¡Solo una mirada y nunca lo olvidarás!",
  ui_story_5058_50580901_56_dialog_content = "Escuché que la joven Diosa Denuo rara vez crecía hasta la madurez y estaba atrapada en una telaraña, así que la liberé.",
  ui_story_5058_50580901_57_dialog_content = "¡Wow! ¿Entonces recibiste la bendición?",
  ui_story_5058_50580901_58_dialog_content = "Mayno ser...?",
  ui_story_5058_50580901_59_dialog_content = "Vamos, Cena, ¡no me digas que nunca has visto uno! ¡No está bien mentir!",
  ui_story_5058_50580901_60_dialog_content = "(¿Ese hombre joven es en realidad Cena? ¿Así que se conocían de antes?)",
  ui_story_5058_50580901_61_dialog_content = "<color=#e8d9bb>¡Zumbar—Zumbar!</color>",
  ui_story_5058_50580901_62_dialog_content = "¡Mamá! Cena! ¿Dónde estás?",
  ui_story_5058_50580901_63_dialog_content = "¡Tormenta de arena! ¡Está engullendo todo el pueblo!",
  ui_story_5058_50580901_64_dialog_content = "¡Lo merecemos por enfurecer a la Diosa Denuo!",
  ui_story_5058_50580901_65_dialog_content = "Mamá... No me dejes detrás...",
  ui_story_5058_50580901_66_dialog_content = "Toma mi mano, Lorelei!",
  ui_story_5058_50580901_67_dialog_content = "Cena...?",
  ui_story_5058_50580901_68_dialog_content = "¡Soy yo, PlayerName!",
  ui_story_5058_50580901_69_dialog_content = "PlayerName...?",
  ui_story_5058_50580901_70_option_content = "¡Despierta!",
  ui_story_5058_50580901_71_dialog_content = "¿Eh...?",
  ui_story_5058_50580901_72_dialog_content = "¡Por fin despiertas, Lorelei! ¡No te asustes, solo soy yo!",
  ui_story_5058_50580901_73_dialog_content = "PlayerName? ¿Qué pasó?",
  ui_story_5058_50580901_74_dialog_content = "No sé, pero todos se desmayaron de repente.",
  ui_story_5058_50580901_75_dialog_content = "Entonces noté que había algo extraño en el aire.",
  ui_story_5058_50580901_76_dialog_content = "Algo que no dejaba de parpadear.",
  ui_story_5058_50580901_77_dialog_content = "Deben estar relacionados con que todos se desmayen. Si encendemos el sistema de ventilación que mencionaste, ¿eliminaría esas cosas?",
  ui_story_5058_50580901_78_dialog_content = "El interruptor está cerca. ¡Sígueme!",
  ui_story_5058_50580901_79_dialog_content = "¡Graagh!",
  ui_story_5058_50580901_80_dialog_content = "¿Más Eclipsites?",
  ui_story_5058_50580901_81_dialog_content = "Solo quedamos los dos... Échame una mano, PlayerName!",
  ui_story_5058_50581001_1_dialog_content = "¡Graaaah!",
  ui_story_5058_50581001_2_dialog_content = "¡Ahhhh!",
  ui_story_5058_50581001_3_dialog_content = "¡No puedes matarme así!",
  ui_story_5058_50581001_4_dialog_content = "Por no mencionar que esta vida ya no es mía, así que, lo siento, ¡no puedo dejarte tenerla!",
  ui_story_5058_50581001_5_dialog_content = "Pero muy pronto, cuando vea a <color=#FFB400>\"ella\"</color>... Por otro lado, probablemente \"ella\" te atrajo aquí.",
  ui_story_5058_50581001_6_dialog_content = "Todavía quiero ver a \"ella\", aunque, y arrepentirme personalmente...",
  ui_story_5058_50581001_7_dialog_content = "(¿Se ha vuelto Cena loco? ¿A quién quiere ver?)",
  ui_story_5058_50581001_8_dialog_content = "¡Rugido!",
  ui_story_5058_50581001_9_dialog_content = "¡Cuidado!",
  ui_story_5058_50581001_10_dialog_content = "Sra. Shashona?",
  ui_story_5058_50581001_11_dialog_content = "¿Qué estás haciendo, Cena? ¿Por qué intentas ser un héroe cuando deberías estar en el hotel ayudando a Lorelei?",
  ui_story_5058_50581001_12_dialog_content = "Esto no tiene nada que ver contigo. Debo enfrentar lo que me ha estado molestando durante gran parte de mi vida solo. Tengo que hacerlo por mí mismo...",
  ui_story_5058_50581001_13_dialog_content = "Gracias por criar y cuidar a Lorelei por mí...",
  ui_story_5058_50581001_14_dialog_content = "Ella es adulta ahora. Deberías escuchar lo que tiene que decir, deja de dictar todo para ella.",
  ui_story_5058_50581001_15_dialog_content = "Eso es. Por favor, vuelve.",
  ui_story_5058_50581001_16_dialog_content = "¿Me estás dando tus últimas palabras?",
  ui_story_5058_50581001_17_dialog_content = "¡Aaaaaah!",
  ui_story_5058_50581001_18_dialog_content = "¡Vamos, ven a por mí!",
  ui_story_5058_50581001_19_dialog_content = "¿Cargando los Eclipsites así nomás? ¿Perdiste la cabeza, Cena?!",
  ui_story_5058_50581001_20_dialog_content = "Esto me está dando dolor de cabeza.",
  ui_story_5058_50581001_21_dialog_content = "Lamentablemente, no soy de los que se quedan mirando mientras alguien más muere.",
  ui_story_5058_50581001_22_dialog_content = "¡Muy bien, ven a probar mis nuevas balas personalizadas y ve si te gustan!",
  ui_story_5058_50581001_23_dialog_content = "<color=#e8d9bb>¡Estallido! ¡Estallido! ¡Estallido!</color>",
  ui_story_5058_50581001_24_dialog_content = "¡Uh!",
  ui_story_5058_50581001_25_dialog_content = "Te lo suplico, Shashona, déjame solo...",
  ui_story_5058_50581001_26_dialog_content = "¿Dejarte solo? ¿Cómo es que eso siempre salió tan fácilmente de la lengua de ambos, tú y Lorelei?",
  ui_story_5058_50581001_27_dialog_content = "Lorelei y yo somos diferentes. Todavía no lo entiendes. Ella nunca quiso alejarse de ti.",
  ui_story_5058_50581001_28_dialog_content = "La razón por la que quería construir un parque de diversiones es porque apreciaba los recuerdos de cuando tú la llevabas allí.",
  ui_story_5058_50581001_29_dialog_content = "¿Eso es lo que ella te dijo? Ese niño...",
  ui_story_5058_50581001_30_dialog_content = "Lo sé. Lo descubrí cuando leí su plan de negocio. Solo estaba...",
  ui_story_5058_50581001_31_dialog_content = "<color=#e8d9bb>¡Guau! ¡Guau!</color>",
  ui_story_5058_50581001_32_dialog_content = "El viento sopla en el valle...?",
  ui_story_5058_50581001_33_dialog_content = "<color=#e8d9bb>silbido—</color>",
  ui_story_5058_50581001_34_dialog_content = "Ya voy...",
  ui_story_5058_50581001_35_dialog_content = "\"¡Ella\" viene!",
  ui_story_5058_50581001_36_dialog_content = "¿Quién viene?",
  ui_story_5058_50581001_37_dialog_content = "<color=#e8d9bb>¡Guau! ¡Guau!</color>",
  ui_story_5058_50581001_38_dialog_content = "Siseo—Siseo—",
  ui_story_5058_50581001_39_dialog_content = "<color=#FFB400>Diosa Denuo</color>... ¡Por fin, te veo!",
  ui_story_5058_50581001_40_dialog_content = "Huí del pueblo y pasé la mitad de mi vida vagando por todo Astra solo para darme cuenta...",
  ui_story_5058_50581001_41_dialog_content = "¡Mi corazón nunca había dejado Denuo!",
  ui_story_5058_50581001_42_dialog_content = "Veo que has venido por tu venganza, Diosa Denuo.",
  ui_story_5058_50581001_43_dialog_content = "Sí, no debería haber sobrevivido. Pensé que podría ganar amnistía reconstruyendo el valle...",
  ui_story_5058_50581001_44_dialog_content = "¡Por favor, aplícame el castigo final!",
  ui_story_5058_50581001_45_dialog_content = "¿Es esa la Diosa Denuo que infligió la maldición?",
  ui_story_5058_50581001_46_dialog_content = "¡Cálmate, Cena! ¡Solo es una mariposa más grande de lo normal!",
  ui_story_5058_50581001_47_dialog_content = "¡No creo que una simple mariposa pueda dirigir nuestras vidas!",
  ui_story_5058_50581001_48_dialog_content = "<color=#e8d9bb>¡Guau! ¡Guau!</color>",
  ui_story_5058_50581001_49_dialog_content = "¡Silbido!",
  ui_story_5058_50581001_50_dialog_content = "¿Qué está lanzando?",
  ui_story_5058_50581001_51_dialog_content = "¡Gahhhh!",
  ui_story_5058_50581001_52_dialog_content = "Aparecen más Eclipsites...",
  ui_story_5058_50581001_53_dialog_content = "Lo entiendo, ¡la mariposa guió a los Eclipsitas al valle! Cena!",
  ui_story_5058_50581001_54_dialog_content = "Cena¿</lock_0>",
  ui_story_5058_50581001_55_dialog_content = "Por favor, castígame...",
  ui_story_5058_50581001_56_dialog_content = "¡Levántate ahora y lucha contra los Eclipsitas!",
  ui_story_5058_50581002_1_dialog_content = "Gah...",
  ui_story_5058_50581002_2_dialog_content = "Estoy mareado... ¿Qué está pasando...? No puedo aguantar...",
  ui_story_5058_50581002_3_dialog_content = "Cena... Cena...",
  ui_story_5058_50581002_4_dialog_content = "Correr... Correr...",
  ui_story_5058_50581002_5_dialog_content = "¿Ah?",
  ui_story_5058_50581002_6_dialog_content = "Correr...",
  ui_story_5058_50581002_7_dialog_content = "Correr...",
  ui_story_5058_50581002_8_dialog_content = "¿Por qué me salvaste? Personas como yo no valen la pena...",
  ui_story_5058_50581002_9_dialog_content = "Correr... Toma Lorelei y... ¡correr...!",
  ui_story_5058_50581002_10_dialog_content = "...",
  ui_story_5058_50581002_11_dialog_content = "Oh...",
  ui_story_5058_50581002_12_dialog_content = "Sra. Shashona?!",
  ui_story_5058_50581002_13_dialog_content = "Coco, Shashona... ¿Por qué ambos salvarían a alguien que nunca tomó la vida en serio como yo?",
  ui_story_5058_50581002_14_dialog_content = "<size=45>¡Silbido, silbido, silbido!</size>",
  ui_story_5058_50581002_15_dialog_content = "¡Gruñido!",
  ui_story_5058_50581002_16_dialog_content = "Pero soy yo quien no debería ser perdonado, no Shashona...",
  ui_story_5058_50581002_17_dialog_content = "Sra. Shashona! ¿Puedes oírme?! Shashona!",
  ui_story_5058_50581002_18_dialog_content = "No...",
  ui_story_5058_50581002_19_dialog_content = "<color=#e8d9bb>*Choque*</color>",
  ui_story_5058_50581002_20_dialog_content = "Ven aquí, Shashona! ¿A dónde fue tu mamá?",
  ui_story_5058_50581002_21_dialog_content = "No lo sé...",
  ui_story_5058_50581002_22_dialog_content = "¡Deja de llorar! ¿No lo sabes? ¿Cómo es que no lo sabes? ¡Tu mamá se escapó, lo entiendes?! ¡Es todo tu culpa!",
  ui_story_5058_50581002_23_dialog_content = "*sollozando*",
  ui_story_5058_50581002_24_dialog_content = "¿Dónde guardó ella el dinero?",
  ui_story_5058_50581002_25_dialog_content = "Papá... Nuestra tienda tiene deudas. Mamá dijo que debemos ahorrar cada centavo, no para que lo gastes en alcohol.",
  ui_story_5058_50581002_26_dialog_content = "¿Por qué sigues escuchándola cuando ya no te quiere? ¡Veo que necesitas una buena paliza!",
  ui_story_5058_50581002_27_dialog_content = "<color=#e8d9bb>¡Zas! ¡Zas!</color>",
  ui_story_5058_50581002_28_dialog_content = "...",
  ui_story_5058_50581002_29_dialog_content = "Pobre niño... No te preocupes, prometo cuidarte hasta que recuperes la salud.",
  ui_story_5058_50581002_30_dialog_content = "Desde la primera vez que te vi, supe que eres la hija enviada desde arriba para compensar mi infancia...",
  ui_story_5058_50581002_31_dialog_content = "Salí del pantano poco a poco solo después de todos los años de pesadilla.",
  ui_story_5058_50581002_32_dialog_content = "A partir de ahora, te convertiré en la chica más feliz del mundo, nunca más serás lastimada.",
  ui_story_5058_50581002_33_dialog_content = "<color=#e8d9bb>Golpeteo de pitter...</color>",
  ui_story_5058_50581002_34_dialog_content = "¿Dónde estoy?",
  ui_story_5058_50581002_35_dialog_content = "Lorelei, mi amor, ¡sal de la lluvia hacia mí!",
  ui_story_5058_50581002_36_dialog_content = "¿Por qué me dejarías pasar bajo tu paraguas?",
  ui_story_5058_50581002_37_dialog_content = "Porque... estuve bajo la lluvia cuando era niño y eso no se sentía bien.",
  ui_story_5058_50581002_38_dialog_content = "Así que no quiero que te mojes por la lluvia ni te lastimes. Quiero que no te preocupes por nada más que crecer sano y salvo.",
  ui_story_5058_50581002_39_dialog_content = "Pero, ¿quién eres? ¿Por qué eres tan bueno conmigo?",
  ui_story_5058_50581002_40_dialog_content = "¿Olvidaste que soy tu mamá? También tienes un papá y un hermanito. Somos la familia más feliz del mundo.",
  ui_story_5058_50581002_41_dialog_content = "¿Hay algo que desees, precioso? ¡Puedo cumplir todos tus deseos!",
  ui_story_5058_50581002_42_dialog_content = "¿Puedo leer libros de cuentos?",
  ui_story_5058_50581002_43_dialog_content = "¡Sí!",
  ui_story_5058_50581002_44_dialog_content = "¿Puedo usar vestidos bonitos?",
  ui_story_5058_50581002_45_dialog_content = "¡Sí!",
  ui_story_5058_50581002_46_dialog_content = "Y... y...",
  ui_story_5058_50581002_47_dialog_content = "¡Puedo llevarte al nuevo parque de diversiones!",
  ui_story_5058_50581002_48_dialog_content = "¡Parque de diversiones! ¿Puedo ir? ¿Papá y hermano también irán con nosotros?",
  ui_story_5058_50581002_49_dialog_content = "Sí. Podemos ir primero ya que papá está de viaje de negocios y tu hermano está en la escuela. Podemos ir todos muchas veces cuando estén de vuelta.",
  ui_story_5058_50581002_50_dialog_content = "¿Puedo dirigir un negocio como papá?",
  ui_story_5058_50581002_51_dialog_content = "Eso es demasiado arriesgado para ti, cariño. He pasado por mucho y sufrido mucho para llegar a donde estoy ahora.",
  ui_story_5058_50581002_52_dialog_content = "Entonces no quiero que mi bebé pase por las mismas cosas...",
  ui_story_5058_50581002_53_dialog_content = "Okay... Oye, me pregunto qué será esa cosa divertida por ahí...",
  ui_story_5058_50581002_54_dialog_content = "Reduce la velocidad, bebé.",
  ui_story_5058_50581002_55_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5058_50581002_56_dialog_content = "Mi paraguas se voló...",
  ui_story_5058_50581002_57_dialog_content = "¡Está bien, mamá! ¡Mira, encontré un lindo paraguas que es incluso más grande que el tuyo!",
  ui_story_5058_50581002_58_dialog_content = "¡También puedo sostenerlo por ti!",
  ui_story_5058_50581002_59_dialog_content = "Suspiro...",
  ui_story_5058_50581002_60_dialog_content = "La lluvia está a punto de parar. ¡Quiero ir allá!",
  ui_story_5058_50581002_61_dialog_content = "¿Dónde estás, mi bebé?",
  ui_story_5058_50581002_62_dialog_content = "¿Precioso? ¡Laurie!<size=45>Lorelei!</size>",
  ui_story_5058_50581002_63_dialog_content = "No me dejes... No me abandones...",
  ui_story_5058_50581002_64_dialog_content = "Espera, ¿cómo es que dije eso?",
  ui_story_5058_50581002_65_dialog_content = "Ya veo, es porque no puedo estar lejos de ti...",
  ui_story_5058_50581002_66_dialog_content = "Soy yo quien te necesitaba cerca...",
  ui_story_5058_50581101_1_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5058_50581101_2_dialog_content = "De acuerdo, el sistema de ventilación está funcionando.",
  ui_story_5058_50581101_3_dialog_content = "Pero, ¿por qué está esa puerta abierta?",
  ui_story_5058_50581101_4_dialog_content = "¿No suele estar cerrado?",
  ui_story_5058_50581101_5_dialog_content = "Hay un sótano aquí solo para aires acondicionados.",
  ui_story_5058_50581101_6_dialog_content = "¿Guardas los aires acondicionados en el subterráneo?",
  ui_story_5058_50581101_7_dialog_content = "Solo el sistema principal. Las tuberías se conectan al exterior.",
  ui_story_5058_50581101_8_dialog_content = "Debido a que ocupa mucho espacio y es muy ruidoso, intentaba averiguar exactamente dónde colocarlo incluso antes de construir el hotel.",
  ui_story_5058_50581101_9_dialog_content = "Hasta que Cena sugirió excavar un sótano para ello. También es su jurisdicción.",
  ui_story_5058_50581101_10_dialog_content = "No pudimos encontrar Cena y Shashona en absoluto. ¿Podrían estar en el sótano?",
  ui_story_5058_50581101_11_dialog_content = "Jefe, PlayerName... ¿Por qué todos están fuera?",
  ui_story_5058_50581101_12_dialog_content = "Bopper? ¡Estás despierto!",
  ui_story_5058_50581101_13_dialog_content = "Pero aún así...",
  ui_story_5058_50581101_14_dialog_content = "Por favor, despierta a todos, Bopper, y luego revisa a los invitados.",
  ui_story_5058_50581101_15_dialog_content = "PlayerName y yo iremos al sótano para ver si Cena está allí abajo.",
  ui_story_5058_50581101_16_dialog_content = "¡Seguro!",
  ui_story_5058_50581101_17_dialog_content = "Hmm, creo que escuché pasos en el sótano. ¿Es ese el Sr. Cena?",
  ui_story_5058_50581101_18_dialog_content = "¿Quizás?",
  ui_story_5058_50581101_19_dialog_content = "<color=#e8d9bb>¡Thump, thump, thump!</color>",
  ui_story_5058_50581101_20_dialog_content = "¡Graagh!",
  ui_story_5058_50581102_1_dialog_content = "<size=45>Cena? ¿Mamá? ¿Estás ahí?</size>",
  ui_story_5058_50581102_2_dialog_content = "¿Tú allí...?",
  ui_story_5058_50581102_X2_dialog_content = "¿Estás ahí?",
  ui_story_5058_50581102_X3_dialog_content = "... ¿Cierto?",
  ui_story_5058_50581102_3_dialog_content = "No es de extrañar que los Eclipsites pudieran entrar al hotel. Obviamente, esto es un túnel y quién sabe a dónde lleva.",
  ui_story_5058_50581102_4_dialog_content = "Cuando salí del sótano para Cena, nunca esperé que él cavara un túnel detrás de mí.",
  ui_story_5058_50581102_5_dialog_content = "Veo muchas mesas, sillas, botellas y latas por aquí, pero parecen ser muy viejas.",
  ui_story_5058_50581102_6_dialog_content = "¿Muy viejo? No me digas...",
  ui_story_5058_50581102_7_dialog_content = "¿Es ese un montón de archivos debajo del taburete?",
  ui_story_5058_50581102_8_dialog_content = "Déjame ver...",
  ui_story_5058_50581102_9_dialog_content = "\"¿Fórmula para el incienso Denuo?\"",
  ui_story_5058_50581102_10_dialog_content = "Solo hablé con Cena sobre eso esta mañana, pero ¿él ya lo estaba investigando antes, o...",
  ui_story_5058_50581102_11_dialog_content = "Dice que el componente más vital para el incienso es la... <color=#FFB400>Diosa Denuo</color>?!",
  ui_story_5058_50581102_12_dialog_content = "¡¿Qué?!",
  ui_story_5058_50581102_13_dialog_content = "Y los documentos pertenecían a... Denuo Village.",
  ui_story_5058_50581102_14_dialog_content = "¿Es este el vestigio de la Aldea Denuo? Pero no sabía que los aldeanos solían hacer incienso de las Diosas Denuo.",
  ui_story_5058_50581102_15_dialog_content = "De ninguna manera Cena no sabía de eso, pero ¿cómo es que nunca me lo dijo?",
  ui_story_5058_50581102_16_dialog_content = "¿Tú y Cena son del pueblo?",
  ui_story_5058_50581102_17_dialog_content = "Lo siento, sucedió que capté un fragmento de tu sueño cuando intenté despertarte.",
  ui_story_5058_50581102_18_dialog_content = "Entonces supongo que también descubriste que Shashona no es mi madre biológica.",
  ui_story_5058_50581102_19_dialog_content = "Pero está bien, PlayerName, no quería ocultar mi pasado.",
  ui_story_5058_50581102_20_dialog_content = "Solo me preocupa que mencionarlo pueda hacer que mi mamá Shashona se sienta mal.",
  ui_story_5058_50581102_21_dialog_content = "Y también viste lo buena que es conmigo, e hizo mucho por mí, así que no debería aferrarme al pasado como lo estoy haciendo ahora.",
  ui_story_5058_50581102_22_dialog_content = "Pero esos recuerdos, felices o tristes, aún aparecerían de vez en cuando.",
  ui_story_5058_50581102_23_dialog_content = "Entonces, ¿conocías a Cena desde hace mucho tiempo?",
  ui_story_5058_50581102_24_dialog_content = "Él era nuestro vecino. Lo llamaba Sr. Cena.",
  ui_story_5058_50581102_25_dialog_content = "Un día, una tormenta de arena sin precedentes golpeó a Denuo. Vi cómo destruía todo el pueblo con mis propios ojos.",
  ui_story_5058_50581102_26_dialog_content = "Me lastimé en el desastre, pero recuerdo que fue Cena quien me salvó.",
  ui_story_5058_50581102_27_dialog_content = "Y también vagamente cómo me entregó a mi mamá adoptiva...",
  ui_story_5058_50581102_28_dialog_content = "Pensé que él haría tiempo para verme, pero nunca lo hizo hasta un encuentro casual justo antes de construir el complejo turístico.",
  ui_story_5058_50581102_29_dialog_content = "De hecho, cuando me desmayé en el valle antes, por alguna razón vi el rostro del joven Cena en un sueño.",
  ui_story_5058_50581102_30_dialog_content = "El túnel subterráneo, el incienso Denuo, los Eclipsites, esa cosa extraña en el aire y la Diosa Denuo...",
  ui_story_5058_50581102_31_dialog_content = "Cena es la clave para todo eso.",
  ui_story_5058_50581102_32_dialog_content = "El tiempo lo ha cambiado a alguien que no reconozco completamente.",
  ui_story_5058_50581102_33_dialog_content = "Pero aún estoy dispuesto a confiar en él, el hermano mayor que me salvó en el desastre.",
  ui_story_5058_50581102_34_dialog_content = "¿Qué estará haciendo él, sin embargo?",
  ui_story_5058_50581102_35_dialog_content = "<color=#e8d9bb>Golpe, golpe, golpe...</color>",
  ui_story_5058_50581102_36_dialog_content = "¿Quién está ahí? ¿Es un Eclipsite?",
  ui_story_5058_50581102_37_dialog_content = "Soy yo...",
  ui_story_5058_50581102_38_dialog_content = "Cena.",
  ui_story_5058_50581201_1_dialog_content = "Suspiro, descubriste este lugar.",
  ui_story_5058_50581201_2_dialog_content = "Tú lees los archivos, ya veo...",
  ui_story_5058_50581201_3_dialog_content = "Tengo muchas preguntas para ti.",
  ui_story_5058_50581201_4_dialog_content = "Espera, ¿Cena lleva a alguien en su espalda?",
  ui_story_5058_50581201_X4_dialog_content = "... ¡Es Shashona!",
  ui_story_5058_50581201_5_dialog_content = "¡¿Mamá?!",
  ui_story_5058_50581201_6_dialog_content = "¿Qué le hiciste a mi mamá, Cena?!",
  ui_story_5058_50581201_7_dialog_content = "Yo...",
  ui_story_5058_50581201_8_dialog_content = "Graah!!",
  ui_story_5058_50581201_9_dialog_content = "Je, aún los alcanzaron.",
  ui_story_5058_50581201_10_dialog_content = "Desocupemos a los Eclipsites primero, Lorelei!",
  ui_story_5058_50581202_1_dialog_content = "Bopper dijo que tú y Lorelei bajaron al sótano pero nunca regresaron, PlayerName. ¡Carleen y yo estábamos a punto de ir a revisar cómo estaban!",
  ui_story_5058_50581202_2_dialog_content = "¿Hay algún otro Eclipsite ahí abajo? ¿Estás bien?",
  ui_story_5058_50581202_3_dialog_content = "Oh, Vice, Carleen... Gracias a Dios que estás despierto.",
  ui_story_5058_50581202_4_dialog_content = "Hay un pasaje al corazón del valle en el sótano, pero lo sellamos, así que no debería haber más Eclipsite.",
  ui_story_5058_50581202_5_dialog_content = "¿Un pasillo en el sótano...?",
  ui_story_5058_50581202_6_dialog_content = "¿Cómo están los invitados, Bopper?",
  ui_story_5058_50581202_7_dialog_content = "Todos han despertado del coma, pero... algunos de ellos están pidiendo esa cosa en el aire.",
  ui_story_5058_50581202_8_dialog_content = "Dijeron que se sintieron bien después de inhalarlo y querían entrar en el mismo coma otra vez!",
  ui_story_5058_50581202_9_dialog_content = "Mi mismo sentimiento. Podría ser un coma, pero desperté asombrosamente refrescado.",
  ui_story_5058_50581202_10_dialog_content = "¡Yo también! Mi cuerpo se sentía ligero y esponjoso como si estuviera volando...",
  ui_story_5058_50581202_11_dialog_content = "Si estoy en lo correcto, esa cosa probablemente tiene una conexión con la Diosa Denuo.",
  ui_story_5058_50581202_12_dialog_content = "O debería decirte... Cena?",
  ui_story_5058_50581202_13_dialog_content = "...",
  ui_story_5058_50581202_14_dialog_content = "Gerente general Cena?! ¡Te estábamos buscando por todas partes! ¿También estabas en el sótano?",
  ui_story_5058_50581202_15_dialog_content = "Dile a los invitados que no hay nada en el aire y véndeles que todo fue una alucinación, Bopper.",
  ui_story_5058_50581202_16_dialog_content = "La adicción se detendrá unos días después de que lleguen a casa.",
  ui_story_5058_50581202_17_dialog_content = "¿Esa cosa causa adicciones?",
  ui_story_5058_50581202_18_dialog_content = "Agh...",
  ui_story_5058_50581202_19_dialog_content = "Shashona? ¿Los Eclipsites lastimaron a ella? Conseguiré un médico de inmediato...",
  ui_story_5058_50581202_20_dialog_content = "Está bien, Bopper. De todos modos, el doctor promedio no puede ayudar.",
  ui_story_5058_50581202_21_dialog_content = "¿Te importaría decirme qué le pasó a mi mamá ahora, Cena?",
  ui_story_5058_50581202_22_dialog_content = "Tuviste razón, Lorelei, todo esto ocurrió por mi culpa.",
  ui_story_5058_50581202_23_dialog_content = "Fui a buscar a la Diosa Denuo en el valle, pero no me di cuenta de que la Sra. Shashona me estaba siguiendo.",
  ui_story_5058_50581202_24_dialog_content = "Entonces, nos encontramos con la Diosa. O más precisamente, una Diosa madura.",
  ui_story_5058_50581202_25_dialog_content = "¿La Diosa Denuo?! ¿La historia es real? ¿Recibiste alguna bendición?",
  ui_story_5058_50581202_26_dialog_content = "Nunca hubo bendiciones ni protección.",
  ui_story_5058_50581202_X26_dialog_content = "Rugió, aleteó sus alas y provocó una tormenta. Si dejó algún \"regalo\"...",
  ui_story_5058_50581202_27_dialog_content = "Es el <color=#FFB400>polvo</color> que liberó. Mucho polvo, de hecho, suficiente para entrar al hotel a través del pasaje subterráneo.",
  ui_story_5058_50581202_28_dialog_content = "¿Polvo? ¿Te refieres a los que brillaban en el aire?",
  ui_story_5058_50581202_29_dialog_content = "Sí. El polvo es una sustancia neuro que causa coma, alucinaciones o recuperación de memoria.",
  ui_story_5058_50581202_30_dialog_content = "He tenido cierta inmunidad desde la infancia, pero no la Sra. Shashona...",
  ui_story_5058_50581202_31_dialog_content = "Ella inhaló demasiado <color=#FFB400>polvo</color> intentando salvarme.",
  ui_story_5058_50581202_32_dialog_content = "Pero todo el polvo se ha ido ahora, ¿por qué mi mamá no se despierta?",
  ui_story_5058_50581202_33_dialog_content = "¿No me despertaste con tu habilidad psíquica, PlayerName? ¿Puedes salvar a mi mamá, por favor?",
  ui_story_5058_50581202_34_dialog_content = "Claro, lo intentaré.",
  ui_story_5058_50581202_35_option_content = "¡Potencia de fuerza!",
  ui_story_5058_50581202_36_dialog_content = "<color=#e8d9bb>Pitter-patter, pitter-patter...</color>",
  ui_story_5058_50581202_37_dialog_content = "¿Esta lloviendo?",
  ui_story_5058_50581202_38_dialog_content = "*Sollozo*",
  ui_story_5058_50581202_39_dialog_content = "¿Dónde estás, Shashona?",
  ui_story_5058_50581202_40_dialog_content = "¿Se derrumba su sueño?",
  ui_story_5058_50581202_41_dialog_content = "<size=45>¡Respóndeme, Shashona!</size>",
  ui_story_5058_50581202_42_dialog_content = "*Sollozo*",
  ui_story_5058_50581202_43_dialog_content = "¿De dónde viene esa voz?",
  ui_story_5058_50581202_44_dialog_content = "Tan frío... Si esto continúa...",
  ui_story_5058_50581202_45_dialog_content = "Voy a ser...",
  ui_story_5058_50581202_46_dialog_content = "<color=#e8d9bb>¡Bofetada!</color>",
  ui_story_5058_50581202_47_dialog_content = "Que demonios...",
  ui_story_5058_50581202_48_dialog_content = "Todo bien, él regresó.",
  ui_story_5058_50581202_49_dialog_content = "Ay, mi cara... Eso dolió.",
  ui_story_5058_50581202_50_dialog_content = "Deja de asustarnos así, PlayerName. ¡No podíamos obtener una respuesta de ti!",
  ui_story_5058_50581202_51_dialog_content = "Así que tuve que recurrir a dar una bofetada. Afortunadamente, funcionó.",
  ui_story_5058_50581202_52_dialog_content = "¿Entonces cómo es?",
  ui_story_5058_50581202_53_dialog_content = "Su sueño se desmoronaba y no podía encontrarla en absoluto... Lo siento.",
  ui_story_5058_50581202_54_dialog_content = "Supongo que ella tomó más polvo de lo que pensé.",
  ui_story_5058_50581202_55_dialog_content = "No me asustes así, mamá... ¡Despierta!",
  ui_story_5058_50581202_56_dialog_content = "Todavía no hemos pasado tiempo en nuestro propio parque y nos quedan muchas otras cosas por hacer juntos...",
  ui_story_5058_50581202_57_dialog_content = "¿Por qué insististe en encontrar a la Diosa Denuo, Cena?",
  ui_story_5058_50581202_58_dialog_content = "El túnel en el sótano y los archivos extraños... Creo que le debes Lorelei una explicación.",
  ui_story_5058_50581202_59_dialog_content = "Había algunas cosas que nunca tuve la oportunidad de decirte antes, Lorelei.",
  ui_story_5058_50581202_60_dialog_content = "Porque entonces aún eras demasiado joven para entenderlas.",
  ui_story_5058_50581202_61_dialog_content = "Evehasta el día de hoy, he luchado sobre si revelarte la verdad o no.",
  ui_story_5058_50581202_62_dialog_content = "Cuando vi lo emocionado que estabas por reconstruir el valle...",
  ui_story_5058_50581202_63_dialog_content = "Bueno, realmente pensé que tal vez podría olvidarme por completo del pasado y comenzar de nuevo, pero estaba equivocado.",
  ui_story_5058_50581202_64_dialog_content = "La Diosa Denuo regresó.",
  ui_story_5058_50581202_65_dialog_content = "Regresó por <color=#FFB400>venganza</color>.",
  ui_story_5058_50581301_1_dialog_content = "En este valle, alguna vez se encontraba un pequeño pueblo autosuficiente.",
  ui_story_5058_50581301_2_dialog_content = "Durante generaciones, los aldeanos creyeron que la <color=#FFB400>Diosa Denuo</color> es su deidad patrona, protegiendo el cañón de los Eclipsites.",
  ui_story_5058_50581301_3_dialog_content = "Se decía que las personas que veían a la Diosa recibirían sus bendiciones y protección.",
  ui_story_5058_50581301_4_dialog_content = "Sin embargo, nadie podía estar seguro de que la Diosa fuera real. Eventualmente, algunos aldeanos se burlaron de la idea.",
  ui_story_5058_50581301_5_dialog_content = "Muchos más comenzaron a ignorar la advertencia de la Diosa en la historia y a saquear los recursos del valle, comenzando con minerales, luego plantas, y luego incluso...",
  ui_story_5058_50581301_6_dialog_content = "¿Guardaste a una Diosa Denuo?",
  ui_story_5058_50581301_7_dialog_content = "¿Era tan bonito como un diamante como en los cuentos? ¿Dónde lo viste?",
  ui_story_5058_50581301_8_dialog_content = "¿Cómo lo pides, papá?",
  ui_story_5058_50581301_9_dialog_content = "Si la Diosa Denuo es real, tenemos que aprovecharla, por supuesto.",
  ui_story_5058_50581301_10_dialog_content = "¡De ninguna manera, la Diosa es nuestra deidad patrona!",
  ui_story_5058_50581301_11_dialog_content = "¿Por qué, mocoso! ¿Cómo te atreves a contestarme con ese trasero perezoso! ¿Crees que todo lo que tienes simplemente cayó del cielo?",
  ui_story_5058_50581301_12_dialog_content = "Puedo cuidarme bien ahora, ¡gracias!",
  ui_story_5058_50581301_13_dialog_content = "¡Bien, sal de mi vista!",
  ui_story_5058_50581301_14_dialog_content = "Dejé mi casa y Coco, la madre biológica de Lorelei, me acogió. Pero para mi sorpresa, mi padre y otros aún descubrieron dónde se esconde la Diosa, encontrando posteriormente muchas mariposas bebé...",
  ui_story_5058_50581301_15_dialog_content = "Querían hacer muestras para vender a los ricos en Umbratón y Lumopolis, solo para descubrir accidentalmente que el polvo de la Diosa podía inducir un coma cómodo.",
  ui_story_5058_50581301_16_dialog_content = "Entonces lo usan para hacer incienso adictivo.",
  ui_story_5058_50581301_17_dialog_content = "El Incienso Denuo...",
  ui_story_5058_50581301_18_dialog_content = "Correcto. El incienso se convirtió en un éxito de la noche a la mañana y en el más vendido en todo Astra.",
  ui_story_5058_50581301_19_dialog_content = "Aunque el proceso de producción requería sacrificar a la Diosa Denuo y el exceso de humo de incienso causaba daño neurológico irreversible, los aldeanos seguían cazando las mariposas como si estuvieran poseídos.",
  ui_story_5058_50581301_20_dialog_content = "Denuo floreció y, para evitar que los extraños robaran la fórmula, los aldeanos cavaron un túnel subterráneo.",
  ui_story_5058_50581301_21_dialog_content = "¡Es el pasillo en la parte trasera del sótano!",
  ui_story_5058_50581301_22_dialog_content = "El túnel conectaba el taller del pueblo con el corazón del valle para facilitar las expediciones de mariposas. Pero nadie esperaba...",
  ui_story_5058_50581301_23_dialog_content = "Por favor, todos, por favor, dejen en paz a la Diosa Denuo!",
  ui_story_5058_50581301_24_dialog_content = "Nunca ha habido un Eclipsite en la historia de Denuo, pero ahora...?",
  ui_story_5058_50581301_25_dialog_content = "Recibimos enjambres de ellos todos los días.",
  ui_story_5058_50581301_26_dialog_content = "¡Es una advertencia de la Diosa Denuo! Estamos tomando tanto del valle que incluso estamos mirando a nuestra deidad patrona.",
  ui_story_5058_50581301_27_dialog_content = "Jaja, ¡jajaja!",
  ui_story_5058_50581301_28_dialog_content = "¿Alguien todavía cree que la Diosa Denuo es nuestra deidad protectora? Me estoy riendo a carcajadas.",
  ui_story_5058_50581301_29_dialog_content = "Un consejo, la mariposa no puede proteger el cañón ya que ni siquiera puede protegerse a sí misma!",
  ui_story_5058_50581301_30_dialog_content = "El único bien que hacen es el polvo que liberan cuando están asustados.",
  ui_story_5058_50581301_31_dialog_content = "Los Eclipsitas son atraídos aquí por la poderosa Lumina en el polvo.",
  ui_story_5058_50581301_32_dialog_content = "No tengas miedo. Ya compramos las armas más avanzadas con el dinero que obtuvimos. Será fácil matar a los Eclipsites.",
  ui_story_5058_50581301_33_dialog_content = "¡Deberías agradecernos por eliminar a los Eclispites y mantener la paz para alguien que está desconectado del tiempo como tú!",
  ui_story_5058_50581301_34_dialog_content = "No necesito tu protección...",
  ui_story_5058_50581301_35_dialog_content = "¡Y por favor deja de destruir los plantones que planté en el valle!",
  ui_story_5058_50581301_36_dialog_content = "Espera, ¿dijo que plantó árboles? Qué broma...",
  ui_story_5058_50581301_37_dialog_content = "Solo recuerdo lo duro que mi madre trabajaba solo para ganarse la vida.",
  ui_story_5058_50581301_38_dialog_content = "¡Nunca supe que ella estaba plantando árboles para el cañón que se iba volviendo gradualmente estéril incluso en ese entonces!",
  ui_story_5058_50581301_39_dialog_content = "Pero si Coco supiera que, docenas de años después, su hija Lorelei devolvió la vida al valle, estaría orgullosa y extasiada.",
  ui_story_5058_50581301_40_dialog_content = "Una lástima que los aldeanos pensaran que ella era tonta por no tomar el dinero en el momento...",
  ui_story_5058_50581301_41_dialog_content = "No sabían que una furiosa Diosa estaba a punto de desatar la perdición sobre Denuo.",
  ui_story_5058_50581301_42_dialog_content = "Ese día, me escabullí al lugar donde los aldeanos guardaban a la Diosa Denuo solo para ver que todas las mariposas habían desaparecido...",
  ui_story_5058_50581301_43_dialog_content = "Las mariposas bebé que cuidaban se habían ido todas, Coco...",
  ui_story_5058_50581301_44_dialog_content = "¿Quién en el pueblo haría tal cosa aparte de tú y yo?",
  ui_story_5058_50581301_45_dialog_content = "<color=#e8d9bb>Whoosh, whoosh...</color>",
  ui_story_5058_50581301_46_dialog_content = "Esto es extraño. Normalmente no hay viento alrededor de esta hora...",
  ui_story_5058_50581301_47_dialog_content = "¿También ves algo en el viento, Cena?",
  ui_story_5058_50581301_48_dialog_content = "¿Polvo?",
  ui_story_5058_50581301_49_dialog_content = "¡¿?!",
  ui_story_5058_50581301_50_dialog_content = "Es la Diosa Denuo... ¡Está furiosa al darse cuenta de que han asesinado a sus hijos!",
  ui_story_5058_50581301_51_dialog_content = "Este viento no va a parar. Tenemos que correr por nuestras vidas, Cena, ¡ahora!",
  ui_story_5058_50581301_52_dialog_content = "Oh no, Lorelei todavía está en casa...",
  ui_story_5058_50581301_53_dialog_content = "Regresamos a buscar Lorelei para poder salir del valle a través de un camino marcado con un poco de vegetación.",
  ui_story_5058_50581301_54_dialog_content = "Pero en el camino, no noté una enorme roca tambaleándose encima...",
  ui_story_5058_50581301_55_dialog_content = "Coco me empujó para salir del camino solo para que ella fuera aplastada por la roca.",
  ui_story_5058_50581301_56_dialog_content = "¿Por qué me salvaste? Personas como yo no valen la pena...",
  ui_story_5058_50581301_57_dialog_content = "Niño tonto... Tos... Siempre te he considerado como familia.",
  ui_story_5058_50581301_58_dialog_content = "Por favor espera, Coco. ¡Encontraré algo para mover la roca que te aplasta!",
  ui_story_5058_50581301_59_dialog_content = "Estoy acabado... Even si mueves la roca, tos... aún no puedo caminar ni salir.",
  ui_story_5058_50581301_60_dialog_content = "Gracias, Cena... por ayudarme todos estos años. Tos... Tengo un último favor que pedirte...",
  ui_story_5058_50581301_61_dialog_content = "Correr... Toma Lorelei y... ¡correr...!",
  ui_story_5058_50581301_62_dialog_content = "Lorelei... ¿Lorelei?!",
  ui_story_5058_50581301_63_dialog_content = "Fue entonces cuando noté que el joven Lorelei había sido derribado al suelo y estaba desmayado.",
  ui_story_5058_50581301_64_dialog_content = "Recogí Lorelei pero antes de irme, me volví hacia Coco solo para ver...",
  ui_story_5058_50581301_65_dialog_content = "El color se desvanece lentamente de su rostro bajo la pesada roca.",
  ui_story_5058_50581301_66_dialog_content = "Impotencia, remordimiento, culpa... Tantas emociones me inundaron de golpe. Creía que todo era un castigo de la Diosa Denuo para los aldeanos.",
  ui_story_5058_50581301_67_dialog_content = "Y yo era el más merecedor de castigo. Si no hubiera encontrado a la joven Diosa, nada de esto habría sucedido.",
  ui_story_5058_50581301_68_dialog_content = "Justo cuando iba a rendirme y aceptar mi muerte en la tormenta de arena, miré a Lorelei y recordé el último deseo de Coco.",
  ui_story_5058_50581301_69_dialog_content = "Para Coco, para Lorelei, debo escapar...",
  ui_story_5058_50581301_70_dialog_content = "La tormenta de arena destruyó completamente a Denuo. Casi nadie sobrevivió aparte de mí y Lorelei.",
  ui_story_5058_50581301_71_dialog_content = "Pero luego me entregaste a Shashona, mi nueva mamá.",
  ui_story_5058_50581301_72_dialog_content = "Ella ya era extremadamente rica. Además, realmente le gustabas, prometió curarte hasta que recuperes la salud y tratarte como si fueras su propio hijo.",
  ui_story_5058_50581301_73_dialog_content = "Eso es mucho mejor que quedarse con un pobreton como yo.",
  ui_story_5058_50581301_74_dialog_content = "Por no mencionar que cumplió su palabra.",
  ui_story_5058_50581301_75_dialog_content = "Entonces, ¿quién liberó a las mariposas bebé el día de esa tormenta de arena?",
  ui_story_5058_50581301_76_dialog_content = "Su mamá. ¿Quién más podría ser?",
  ui_story_5058_50581301_77_dialog_content = "¡La Diosa Denuo liberó a sus niños antes de castigar al pueblo!",
  ui_story_5058_50581301_78_dialog_content = "Entonces, ¿no solo no protegió a la gente, sino que también se dio la vuelta y los castigó?",
  ui_story_5058_50581301_79_dialog_content = "¿Por qué no me dijiste eso desde el comienzo?",
  ui_story_5058_50581301_80_dialog_content = "Todavía eras muy joven entonces. Coco tampoco quería que lo supieras.",
  ui_story_5058_50581301_81_dialog_content = "¿Qué tal ahora? ¡Sabías la verdad y aún así aceptaste usar a la Diosa como un truco publicitario para promocionar el parque!",
  ui_story_5058_50581301_82_dialog_content = "¿Por qué nos dejarías ir a buscar la mariposa en el valle?",
  ui_story_5058_50581301_83_dialog_content = "¿Por qué me dirías que harías el Incienso Denuo que quería la Junta?",
  ui_story_5058_50581301_84_dialog_content = "¿Estás intentando repetir esa tragedia de nuevo?",
  ui_story_5058_50581301_85_dialog_content = "¿O en realidad estás esperando el llamado castigo de la Diosa y planeaste todo?",
  ui_story_5058_50581301_86_dialog_content = "Bueno, ¿cómo debería responder a todo eso?",
  ui_story_5058_50581301_87_dialog_content = "Mayser sí, tal vez no...",
  ui_story_5058_50581301_88_dialog_content = "Desde que te di a la Sra. Shashona, he estado vagando por Astra...",
  ui_story_5058_50581301_X88_dialog_content = "Después de todo por lo que he pasado, aún no pude sacar la tormenta de arena de mi cabeza.",
  ui_story_5058_50581301_89_dialog_content = "Maydebería haber muerto ahí mismo, no vivir como un cobarde.",
  ui_story_5058_50581301_90_dialog_content = "Así que...|Regresé.",
  ui_story_5058_50581301_X90_dialog_content = "Aunque habían pasado más de diez años, finalmente reuní el valor para regresar y enfrentar el juicio de la Diosa Denuo.",
  ui_story_5058_50581301_91_dialog_content = "Pero cuando llegué, descubrí que el Valle de Denuo ya se había convertido en un desierto, y la Diosa Denuo no estaba por ninguna parte.",
  ui_story_5058_50581301_92_dialog_content = "Justo cuando pensaba en terminarlo todo, ¡descubrí que alguien había comenzado a reconstruir el Valle de Denuo!",
  ui_story_5058_50581301_93_dialog_content = "En ese momento, no sabía nada. Simplemente no quería ver que el único hogar que había conocido se convirtiera en un páramo.",
  ui_story_5058_50581301_94_dialog_content = "Fue en ese instante que vi a Coco, viviendo a través de ti. Sé que si ella hubiera estado allí, habría hecho exactamente lo mismo...",
  ui_story_5058_50581301_95_dialog_content = "La aldea Denuo ya había sido castigada por abandonar su fe, y el valle fue arrasado como resultado.",
  ui_story_5058_50581301_96_dialog_content = "Pero, considerando que la Diosa Denuo parecía haber desaparecido del valle, ¿podría su castigo ya haber cumplido su curso?",
  ui_story_5058_50581301_97_dialog_content = "Mayser... Mayser después de reconstruir el valle, todo volverá a como era antes, a antes de que la Diosa Denuo fuera despreciada.",
  ui_story_5058_50581301_98_dialog_content = "Entonces, tomé mi decisión. Elegí vivir... para ayudarte a restaurar el valle a su antigua gloria...",
  ui_story_5058_50581301_99_dialog_content = "¡Quería presenciar el glorioso renacimiento del valle con mis propios ojos!",
  ui_story_5058_50581301_100_dialog_content = "Te estás olvidando del pasaje subterráneo...",
  ui_story_5058_50581301_101_dialog_content = "Pensé que hasta el último rastro de la aldea Denuo había sido arrastrado por la tormenta de arena.",
  ui_story_5058_50581301_102_dialog_content = "Años después, descubrí que el túnel que los aldeanos habían utilizado para atrapar a la Diosa Denuo seguía intacto.",
  ui_story_5058_50581301_103_dialog_content = "Me encontré enfrentando un dilema. Consideré prender fuego a toda la caverna y enterrarla para siempre...",
  ui_story_5058_50581301_104_dialog_content = "Pero Denuo Village es mi hogar. ¿Cómo podría obligarme a destruir el último vestigio de mi pueblo?",
  ui_story_5058_50581301_105_dialog_content = "Creo que quizás, algún día, dejaré la verdad sobre lo que pasó en el pueblo en tus manos, Lorelei. Tú puedes decidir por ti mismo qué sucede con las ruinas allá abajo.",
  ui_story_5058_50581301_106_dialog_content = "¡Nunca esperé que este día llegara tan pronto! Supongo que no pensé que la Diosa Denuo seguiría guardando un resentimiento tan duradero contra los aldeanos...",
  ui_story_5058_50581301_107_dialog_content = "¡Ella ha regresado para reclamar venganza! ¡Regresar para castigarme, el pecador que escapó de una muerte cruel bajo las arenas!",
  ui_story_5058_50581301_108_dialog_content = "¡Basta! Cena, te estás tomando todo esto demasiado en serio.",
  ui_story_5058_50581301_109_dialog_content = "Venganza, pecado... Estas ideas salvajes son solo productos de una mente hiperactiva.",
  ui_story_5058_50581301_110_dialog_content = "Even si las Diosas Denuo poseen algún poder místico, no es del tipo que pueda causar una tormenta de arena capaz de destruir un pueblo entero.",
  ui_story_5058_50581301_111_dialog_content = "Maytal vez no sea algún tipo de castigo divino, sino más bien los aldeanos de Denuo cosechando lo que sembraron.",
  ui_story_5058_50581301_112_dialog_content = "Los animales y plantas del valle crearon un santuario para los habitantes de esta tierra estéril, pero cuando ese equilibrio se rompió, era natural que su refugio desapareciera.",
  ui_story_5058_50581301_113_dialog_content = "Lorelei, por extraño que parezca... He decidido ir a buscar a la Diosa Denuo y finalmente aceptar el castigo que me corresponde.",
  ui_story_5058_50581301_114_dialog_content = "Si lo que dices es verdad... ¿no debería aceptar algún tipo de castigo? Quiero decir, también formaba parte del pueblo Denuo en ese entonces.",
  ui_story_5058_50581301_115_dialog_content = "No tuviste nada que ver con todo eso. Solo eras un niño en ese entonces, ni siquiera sabías lo que estaba pasando.",
  ui_story_5058_50581301_116_dialog_content = "Y... Y le prometí a Coco que me aseguraría de que vivas una vida larga y feliz!",
  ui_story_5058_50581301_117_dialog_content = "¿Feliz? ¿Cómo puedo estar feliz cuando mi mamá está en coma!",
  ui_story_5058_50581301_118_dialog_content = "No había anticipado que algo tan serio le sucediera a Shashona, pero es cierto que se sabe que algunos caen en un estado vegetativo persistente después de inhalar cantidades excesivas de Incienso Denuo.",
  ui_story_5058_50581301_119_dialog_content = "¡¿Qué?!",
  ui_story_5058_50581301_120_dialog_content = "Pero recuerdo... hay un antídoto que puede neutralizar el veneno en las escamas de la Diosa Denuo, aunque es bastante difícil de conseguir.",
  ui_story_5058_50581301_121_dialog_content = "¡No me importa qué tan difícil sea! Por favor, ¡sólo dime cómo conseguirlo!",
  ui_story_5058_50581301_122_dialog_content = "Bueno, es una especie de mucosidad.",
  ui_story_5058_50581301_123_dialog_content = "Para ser precisos, es el moco que la Diosa Denuo produce al producir huevos.",
  ui_story_5058_50581401_1_dialog_content = "<color=#e8d9bb>*Crowmurmurando*</color>",
  ui_story_5058_50581401_2_dialog_content = "¿Qué está pasando? Parece que tenemos clientes descontentos en nuestras manos...",
  ui_story_5058_50581401_3_dialog_content = "Jefe, es el personal...",
  ui_story_5058_50581401_4_dialog_content = "EveTodos escucharon la historia recién sobre la Diosa Denuo que viene a vengarse, y todos están aterrorizados. ¡Un montón de ellos quieren renunciar y salir de aquí!",
  ui_story_5058_50581401_5_dialog_content = "Oh...",
  ui_story_5058_50581401_6_dialog_content = "Jefe, esta situación necesita resolverse de inmediato... ¿Qué tal si cerramos el resort por un tiempo, ya sabe, por la seguridad del personal y los huéspedes...?",
  ui_story_5058_50581401_7_dialog_content = "¡Cierre el complejo y déjenos ir, jefe!",
  ui_story_5058_50581401_8_dialog_content = "¡No deberíamos sufrir la ira de la Diosa Denuo!",
  ui_story_5058_50581401_9_dialog_content = "EveTodos, por favor tranquilícense por un momento.",
  ui_story_5058_50581401_10_dialog_content = "¡Déjalo así, jefe!",
  ui_story_5058_50581401_11_dialog_content = "¡Vamos a casa! ¡Vámonos!",
  ui_story_5058_50581401_12_dialog_content = "Mis propios empleados... ya ni siquiera confían en mí.",
  ui_story_5058_50581401_13_dialog_content = "¿Todos simplemente me van a dar la espalda?",
  ui_story_5058_50581401_14_dialog_content = "Finalmente llegué hasta aquí, pero nunca pensé que algo así sucedería... y todo es por mi propia imprudencia...",
  ui_story_5058_50581401_15_dialog_content = "Quizás debería haber escuchado a mamá desde el principio en lugar de esforzarme tanto por demostrar mi valía...",
  ui_story_5058_50581401_16_dialog_content = "Todo es mi culpa... Aún no tengo lo necesario para hacer que un negocio como este funcione...",
  ui_story_5058_50581401_17_dialog_content = "No puedes pensar así, Lorelei!",
  ui_story_5058_50581401_18_dialog_content = "Sí, Lorelei! Este tipo de charla derrotista no es propio de ti en absoluto.",
  ui_story_5058_50581401_19_dialog_content = "Solo piensa en cómo lograste reconstruir el valle y establecer un complejo tan lujoso aquí... Obviamente, ¡eres un experto en este tipo de cosas!",
  ui_story_5058_50581401_20_dialog_content = "Estoy totalmente de acuerdo, ¡no creo que necesites probarte a ti mismo ante nadie!",
  ui_story_5058_50581401_21_dialog_content = "Pero mamá nunca ha tenido algo bueno que decir sobre mí, y ahora está en coma, y todo es mi culpa...",
  ui_story_5058_50581401_22_dialog_content = "Estoy seguro de que Shashona sabe lo genial que eres.",
  ui_story_5058_50581401_23_dialog_content = "Desde el momento en que la conocí, ¡pude notar lo orgullosa que estaba de su complejo turístico!",
  ui_story_5058_50581401_24_dialog_content = "Pero mamá... ella nunca me dijo una buena palabra sobre el complejo turístico.",
  ui_story_5058_50581401_25_dialog_content = "Oh, yo tampoco lo habría adivinado... Entonces, resulta que la astuta Sra. Shashona estaba haciendo todo lo posible para esconder sus verdaderos sentimientos de su hija.",
  ui_story_5058_50581401_26_dialog_content = "Parece que simplemente no estaba lista para—",
  ui_story_5058_50581401_27_dialog_content = "¡No! Lorelei...",
  ui_story_5058_50581401_28_dialog_content = "¿Mamá?",
  ui_story_5058_50581401_29_dialog_content = "No me dejes...",
  ui_story_5058_50581401_30_dialog_content = "Nunca planeé dejarte, Mamá... ¿Me escuchas?",
  ui_story_5058_50581401_31_dialog_content = "...",
  ui_story_5058_50581401_32_dialog_content = "Entonces, ¿esto es de lo que has tenido miedo todo este tiempo?",
  ui_story_5058_50581401_33_dialog_content = "Mamá...",
  ui_story_5058_50581401_34_dialog_content = "Jefe, el personal... Todos siguen esperando una respuesta...",
  ui_story_5058_50581401_35_dialog_content = "Entiendo.",
  ui_story_5058_50581401_36_dialog_content = "Mamá, no me voy a rendir ahora.",
  ui_story_5058_50581401_37_dialog_content = "No llegué a donde estoy hoy por nadie más que yo mismo... Tengo mi propio sueño.",
  ui_story_5058_50581401_38_dialog_content = "Elegí seguir el camino más difícil ante mí para hacer realidad este sueño, y me di cuenta de algo hace mucho tiempo.",
  ui_story_5058_50581401_39_dialog_content = "No importa qué dificultades se presenten en mi camino, ¡tengo que enfrentarlas de frente!",
  ui_story_5058_50581401_40_dialog_content = "No como hija, no como una emprendedora ingenua, no como una oportunista lucrativa...",
  ui_story_5058_50581401_41_dialog_content = "¡Pero como un jefe con empleados a guiar y clientes a servir! ¡Un jefe que enfrenta y resuelve valientemente sus problemas!",
  ui_story_5058_50581401_42_dialog_content = "¡Parece que el Lorelei que conocemos y amamos ha regresado!",
  ui_story_5058_50581401_43_dialog_content = "Gracias, PlayerName...",
  ui_story_5058_50581401_44_dialog_content = "¡Empleados del Denuo Valley Resort! ¡Escuchen!",
  ui_story_5058_50581401_45_dialog_content = "Sé que todos están sintiendo miedo en este momento y deben tener muchas preguntas. No realicé una investigación preliminar exhaustiva del área y pido disculpas por esto.",
  ui_story_5058_50581401_46_dialog_content = "Entonces, primero, solo quiero decir... ¡Lo siento mucho, todos!",
  ui_story_5058_50581401_47_dialog_content = "Hacer de este complejo turístico un éxito... Bueno, es mi sueño.",
  ui_story_5058_50581401_48_dialog_content = "Nos ha costado mucha sangre, sudor y lágrimas transformar juntos este valle.",
  ui_story_5058_50581401_49_dialog_content = "Y debido a esto, el Denuo Valley Resort ya no es simplemente mi sueño.",
  ui_story_5058_50581401_50_dialog_content = "EveCada ladrillo de este lugar, cada casilla, lleva la marca inmortal del esfuerzo de todos. Este es nuestro sueño compartido, ¡esta es nuestra casa!",
  ui_story_5058_50581401_51_dialog_content = "Entonces, nos hemos encontrado con nuestro primer obstáculo. No quiero cerrar el complejo y rendirme instantáneamente solo por esto...",
  ui_story_5058_50581401_52_dialog_content = "No puedo darle la espalda a nuestro sueño, ¡no abandonaré la casa que trabajamos tanto para construir!",
  ui_story_5058_50581401_53_dialog_content = "Sé que todos están asustados, sé que están ansiosos y, para ser honesto, esta es la primera vez que me enfrento a un problema como este.",
  ui_story_5058_50581401_54_dialog_content = "Pero quiero que todos sepan que estoy tomando el control de la situación, y prometo que resolveré este asunto lo más rápido que pueda.",
  ui_story_5058_50581401_55_dialog_content = "Aunque el futuro sea incierto, por favor, solo dame un poco más de tiempo... ¡Prometo que lo arreglaré!",
  ui_story_5058_50581401_56_dialog_content = "...",
  ui_story_5058_50581401_57_dialog_content = "Ya que el jefe lo puso de esa manera...",
  ui_story_5058_50581401_58_dialog_content = "¡Sí quiero que mi familia visite el complejo turístico!",
  ui_story_5058_50581401_59_dialog_content = "Y quiero que mis amigos vean el increíble lugar en el que trabajo...",
  ui_story_5058_50581401_60_dialog_content = "También espero que puedan encontrar la fuerza para regresar a sus puestos y continuar sirviendo a nuestros clientes actuales de la mejor manera posible.",
  ui_story_5058_50581401_61_dialog_content = "Necesito saber que todos ustedes me apoyan! Por favor, denme el valor para seguir adelante y encargarme de todo esto!",
  ui_story_5058_50581401_62_dialog_content = "Creo que mientras trabajemos juntos, definitivamente superaremos este pequeño contratiempo y pondremos el complejo turístico de nuevo en marcha!",
  ui_story_5058_50581401_63_dialog_content = "Creo en cada uno de ustedes... ¿Creen en mí?",
  ui_story_5058_50581401_64_dialog_content = "...",
  ui_story_5058_50581401_65_dialog_content = "Jefe, yo... ¡Creo en ti!",
  ui_story_5058_50581401_66_dialog_content = "Confiamos en ti, Lorelei!",
  ui_story_5058_50581401_67_dialog_content = "¡Confía en ti, confía en ti, confía en ti!",
  ui_story_5058_50581401_68_dialog_content = "Lorelei... parece más maduro que antes, ¿no crees?",
  ui_story_5058_50581401_69_dialog_content = "Creo que siempre ha sido una empresaria bastante madura, pero ahora tiene un poco más de fuerza y convicción de lo que solía tener.",
  ui_story_5058_50581401_70_dialog_content = "PlayerName, ¿de qué están murmurando ustedes dos?",
  ui_story_5058_50581401_71_dialog_content = "¡Él estaba cantando tus alabanzas, Lorelei!",
  ui_story_5058_50581401_72_dialog_content = "¿Ah?",
  ui_story_5058_50581401_73_dialog_content = "Gracias, PlayerName... Gracias a todos...",
  ui_story_5058_50581401_74_dialog_content = "Pero ahora necesito que todos me echen una mano.",
  ui_story_5058_50581401_75_dialog_content = "De acuerdo, nos encargaremos de los Eclipsites restantes por aquí.",
  ui_story_5058_50581401_76_dialog_content = "Y también me gustaría llegar al fondo de todo esto.",
  ui_story_5058_50581401_77_dialog_content = "Te refieres a...",
  ui_story_5058_50581401_78_dialog_content = "Necesito adentrarme en el valle y encontrar a la Diosa Denuo, averiguar qué quiere y... encontrar un antídoto para mi madre.",
  ui_story_5058_50581401_79_dialog_content = "Parece que vamos en la misma dirección, entonces.",
  ui_story_5058_50581401_80_dialog_content = "Ven conmigo. Solo ten cuidado, ese polvo de escamas parece atraer a los Eclipsites.",
  ui_story_5058_50581401_81_dialog_content = "Además, cubre tu nariz y boca con un paño húmedo para que no colapses antes de que lleguemos allí.",
  ui_story_5058_50581501_1_dialog_content = "¡Torrente rápido!",
  ui_story_5058_50581501_2_dialog_content = "Oh...",
  ui_story_5058_50581501_3_dialog_content = "¡Hay tantos Eclipsites por aquí!",
  ui_story_5058_50581501_4_dialog_content = "¿Por qué el polvo de la escala no está afectando a los Eclipsites?",
  ui_story_5058_50581501_5_dialog_content = "Supongo que es porque su fisiología es diferente a la nuestra, aunque se sienten atraídos y se emocionan por la Lumina en el polvo.",
  ui_story_5058_50581501_6_dialog_content = "Está claro dónde están las concentraciones más altas de polvo de escala, ahí es donde encontrarás los grupos más grandes de Eclipsites...",
  ui_story_5058_50581501_7_dialog_content = "¡Rugido!",
  ui_story_5058_50581501_8_dialog_content = "¡Fuera de mi camino!",
  ui_story_5058_50581501_9_dialog_content = "Parece que cuanto más avanzamos, más polvo de escamas hay. ¿Eso significa que nos estamos acercando a la Diosa Denuo?",
  ui_story_5058_50581501_10_dialog_content = "Espera, siento algo lleno de Lumina cargando hacia nosotros...",
  ui_story_5058_50581501_11_dialog_content = "May¿será un Auroriano que viene a echarnos una mano?",
  ui_story_5058_50581501_12_dialog_content = "Pero no pedí a nadie más que viniera a ayudarnos.",
  ui_story_5058_50581501_13_dialog_content = "Bueno, supongo que eso deja solo una posibilidad...",
  ui_story_5058_50581501_14_dialog_content = "¡Está aquí!",
  ui_story_5058_50581501_15_dialog_content = "<color=#e8d9bb>¡Guau! ¡Guau!</color>",
  ui_story_5058_50581501_16_dialog_content = "<size=45>¡Silbido!</size>",
  ui_story_5058_50581501_17_dialog_content = "¿Eh? ¡Es...!",
  ui_story_5058_50581501_18_dialog_content = "Es la Diosa Denuo...",
  ui_story_5058_50581501_19_dialog_content = "!!!",
  ui_story_5058_50581501_20_dialog_content = "¡Pero esto es completamente diferente de esa linda pegatina de la Diosa Denuo!",
  ui_story_5058_50581501_21_dialog_content = "Esa pegatina te muestra cómo se ven estas cosas cuando acaban de eclosionar. Esta Diosa Denuo flotando frente a nosotros en este momento es una <color=#FFB400>reina mariposa</color> completamente desarrollada, lista para poner sus propios huevos...",
  ui_story_5058_50581501_22_dialog_content = "<size=45>¡Silbido, silbido, silbido!</size>",
  ui_story_5058_50581501_23_dialog_content = "<color=#e8d9bb>¡Guau! ¡Guau!</color>",
  ui_story_5058_50581501_24_dialog_content = "EveTodos, encuentren una planta detrás de la cual esconderse para no ser arrastrados por el aleteo de las alas de la Diosa Denuo!",
  ui_story_5058_50581501_25_dialog_content = "Diosa Denuo, las leyendas dicen que posees una sabiduría incomparable, así que seguramente puedes entender lo que te estoy diciendo ahora mismo, ¿verdad?",
  ui_story_5058_50581501_26_dialog_content = "<size=45>¡Silbido!</size>",
  ui_story_5058_50581501_27_dialog_content = "¡Cuidado, Lorelei!",
  ui_story_5058_50581501_28_dialog_content = "Oh...",
  ui_story_5058_50581501_29_dialog_content = "Cena¿?</translation>",
  ui_story_5058_50581501_30_dialog_content = "¿Recuerdas a alguien mencionando que la Diosa Denuo todavía era tan fuerte?",
  ui_story_5058_50581501_31_dialog_content = "No me parece.",
  ui_story_5058_50581501_32_dialog_content = "Tose, tose... Parece que la ira de la Diosa Denuo no será tan fácil de aplacar...",
  ui_story_5058_50581501_33_dialog_content = "Sal de aquí, rápido. Déjame encargarme de esto yo mismo.",
  ui_story_5058_50581501_34_dialog_content = "¡De qué diablos estás hablando!",
  ui_story_5058_50581501_35_dialog_content = "<size=45>¡Silbido, silbido, silbido!</size>",
  ui_story_5058_50581502_1_dialog_content = "Diosa Denuo, ¡esto es un gran malentendido!",
  ui_story_5058_50581502_2_dialog_content = "No deseamos hacerte daño... ¡No podríamos aunque quisiéramos!",
  ui_story_5058_50581502_3_dialog_content = "<size=45>¡Silbido, silbido, silbido!</size>",
  ui_story_5058_50581502_4_dialog_content = "Mi mamá está en coma... Inhaló demasiado polvo de tus escamas, y tú eres el único que puede—",
  ui_story_5058_50581502_5_dialog_content = "No sirve...",
  ui_story_5058_50581502_6_dialog_content = "¿Por qué? Cena, ¿no puedes comunicarte con insectos? ¿Sabes lo que dice la Diosa Denuo?",
  ui_story_5058_50581502_7_dialog_content = "La Diosa Denuo... solo dice \"nunca perdonar, nunca perdonar, nunca perdonar\" una y otra vez...",
  ui_story_5058_50581502_8_dialog_content = "!!!",
  ui_story_5058_50581502_9_dialog_content = "¡Ahora todos saben, ella ha regresado por venganza!",
  ui_story_5058_50581502_10_dialog_content = "<size=45>¡Silbido, silbido, silbido!</size>",
  ui_story_5058_50581502_11_dialog_content = "Oh...",
  ui_story_5058_50581502_12_dialog_content = "Lorelei¡¡¡",
  ui_story_5058_50581502_13_dialog_content = "¿Estás bien, Lorelei?!",
  ui_story_5058_50581502_14_dialog_content = "Tose, tose... Yo... Yo aún sigo aguantando...",
  ui_story_5058_50581502_15_dialog_content = "Si nos vemos obligados a esforzarnos así por mucho más tiempo, me temo que las cosas podrían dar un giro para peor.",
  ui_story_5058_50581502_16_dialog_content = "Vamos, Lorelei! Déjame ayudarte a ponerte de pie!",
  ui_story_5058_50581502_17_dialog_content = "Hey... ¿Qué está a punto de caer de este árbol?",
  ui_story_5058_50581502_18_dialog_content = "Diosa Denuo, si quieres castigar a alguien, castígame a mí, ¡y solo a mí!",
  ui_story_5058_50581502_19_dialog_content = "Hace más de diez años, casualmente salvé a una Diosa Denuo y fui lo suficientemente descuidado como para dejar que todo el pueblo se enterara de ello...",
  ui_story_5058_50581502_20_dialog_content = "¿Silbido...?",
  ui_story_5058_50581502_21_dialog_content = "Así es, fui yo... Si no fuera por mis acciones, la gente del pueblo Denuo nunca habría capturado a la Diosa Denuo sin razón...",
  ui_story_5058_50581502_22_dialog_content = "¡Soy yo quien debería haber enfrentado el castigo divino en esa tormenta de arena! Pero en lugar de eso, hui...",
  ui_story_5058_50581502_23_dialog_content = "¡Tuve que huir! Alguien muy importante para mí me dio una misión, ¡y tenía que completarla!",
  ui_story_5058_50581502_24_dialog_content = "Huí hace más de diez años y mi alma ha estado atormentada desde entonces. ¡Estoy aquí frente a ti buscando redención!",
  ui_story_5058_50581502_25_dialog_content = "Pero por favor, déjame cargar solo con los pecados del pasado.",
  ui_story_5058_50581502_26_dialog_content = "Esto no tiene nada que ver con Lorelei y esos otros jóvenes allá atrás, ni con los huéspedes en el complejo turístico...",
  ui_story_5058_50581502_27_dialog_content = "¡Estoy dispuesto a dar mi vida para arreglar esto!",
  ui_story_5058_50581502_28_dialog_content = "Por favor, solo dáles el antídoto para el veneno del polvo de escamas y déjalos ir...",
  ui_story_5058_50581502_29_dialog_content = "(¿Parece que... la Diosa Denuo... se ha calmado?)",
  ui_story_5058_50581502_30_dialog_content = "Diosa Denuo, por favor... concédeme el final más doloroso que puedas sobre tus alas mortales...",
  ui_story_5058_50581502_31_dialog_content = "Maydebería simplemente terminar mi vida ante tus ojos con mi propia arma...",
  ui_story_5058_50581502_32_dialog_content = "¿Qué estás haciendo, Cena?!",
  ui_story_5058_50581502_33_dialog_content = "Me di cuenta cuando nos encontramos de nuevo en aquel entonces cómo siempre intentas presentarte como este chico maduro que sabe tanto sobre el mundo!",
  ui_story_5058_50581502_34_dialog_content = "La verdad es que ¡no has madurado en absoluto! ¡Todo lo que haces es evitar tus problemas en lugar de intentar superarlos!",
  ui_story_5058_50581502_35_dialog_content = "¿La única cosa por la que vives es realmente solo la redención? ¡Ni siquiera hiciste algo malo en aquel entonces!",
  ui_story_5058_50581502_36_dialog_content = "Mamá... Coco te salvó en aquel entonces, y Shashona también te salvó.",
  ui_story_5058_50581502_37_dialog_content = "¡Y la razón por la que lo hicieron es porque pensaron que valías la pena salvar! ¡Pero solo mírate! ¿Por qué insistes en intentar tirar tu vida de esta manera?",
  ui_story_5058_50581502_38_dialog_content = "¿Quieres que la gente diga que mis madres eran tontas y dieron sus vidas en vano?",
  ui_story_5058_50581502_39_dialog_content = "No... Eso no es...",
  ui_story_5058_50581502_40_dialog_content = "Diosa Denuo, por favor escúchame. ¡Todo lo que quiero hacer es aclarar este malentendido entre nosotros!",
  ui_story_5058_50581502_41_dialog_content = "¿Siseo?",
  ui_story_5058_50581502_42_dialog_content = "Coco me dijo que tú otorgas bendiciones y protección a aquellos que conoces...",
  ui_story_5058_50581502_43_dialog_content = "Creo en lo que ella me dijo, y también creo que nunca serías tan cruel como para imponer una forma tan retorcida de supuesto castigo divino.",
  ui_story_5058_50581502_44_dialog_content = "¡Regresé al Valle Denuo para devolverle la vida a este lugar! ¡No cometeré los mismos errores que los aldeanos hicieron en aquel entonces!",
  ui_story_5058_50581502_45_dialog_content = "Me alegra que también hayas regresado al Valle de Denuo, porque esto significa que todo lo que he hecho para restaurar el valle no ha sido en vano...",
  ui_story_5058_50581502_46_dialog_content = "El hecho de que volverías a poner tus huevos en el valle es prueba suficiente de que ¡he marcado la diferencia!",
  ui_story_5058_50581502_47_dialog_content = "¡Silbido, silbido, silbido!",
  ui_story_5058_50581502_48_dialog_content = "¡Diosa Denuo! ¡No quiero hacerle daño a tu joven!",
  ui_story_5058_50581502_49_dialog_content = "Recogí esto hace un momento sin saber qué era... ¡Aquí, déjame devolvértelo!",
  ui_story_5058_50581502_50_dialog_content = "Entiendo... Pensaste que queríamos lastimar a tu niño, y por eso te enojaste tanto. ¿Verdad?",
  ui_story_5058_50581502_51_dialog_content = "¡Silbido, silbido, silbido, silbido!",
  ui_story_5058_50581502_52_dialog_content = "Ella vio... que llevábamos redes e intentábamos atrapar a sus hijos.",
  ui_story_5058_50581502_53_dialog_content = "¡Todo esto es mi culpa! Aunque nací en el Valle de Denuo, apenas sé algo sobre ti...",
  ui_story_5058_50581502_54_dialog_content = "Llevé a todos aquí al valle... De hecho, esperaba que tal vez pudiera encontrar una forma de ayudar a las Diosas Denuo a florecer aquí de nuevo...",
  ui_story_5058_50581502_55_dialog_content = "Solo ahora entiendo lo ingenuo y arrogante que fue de mi parte pensar eso.",
  ui_story_5058_50581502_56_dialog_content = "Este valle es mi hogar, y el complejo turístico es un sueño que muchos de nosotros apreciamos... ¡Por eso prometo proteger este lugar con más pasión que nadie!",
  ui_story_5058_50581502_57_dialog_content = "Te imploro, ¡por favor confía en mí! ¡Sé que puedo encontrar una manera de proteger tu hábitat natural y evitar que tus crías sean perturbadas!",
  ui_story_5058_50581502_58_dialog_content = "¿Siseo?",
  ui_story_5058_50581502_59_dialog_content = "¿Quieres preguntarme algo?",
  ui_story_5058_50581502_60_dialog_content = "Sí, creo que vale la pena confiar en ella. ¡Su mamá, Coco, también quería proteger el Valle de Denuo y sus mariposas hace tiempo!",
  ui_story_5058_50581502_61_dialog_content = "Creo que ha heredado los ideales de Coco... ¡Por eso creo en ella!",
  ui_story_5058_50581502_62_dialog_content = "Silbido, silbido...",
  ui_story_5058_50581502_63_dialog_content = "¡La Diosa Denuo ya no parece estar tan enojada!",
  ui_story_5058_50581502_64_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5058_50581502_65_dialog_content = "Silbido...",
  ui_story_5058_50581502_66_dialog_content = "¿Eh? ¿Tu niño está a punto de salir de su capullo?! ¿Qué-Qué debemos hacer...? ¡Todavía lo tengo en mis manos!",
  ui_story_5058_50581502_67_dialog_content = "<color=#e8d9bb>La Diosa Denuo tomó el capullo brillante de la mano de Lorelei.</color>",
  ui_story_5058_50581502_68_dialog_content = "Ya puedes salir...",
  ui_story_5058_50581502_69_dialog_content = "Mamá...",
  ui_story_5058_50581502_70_dialog_content = "Bien hecho, mi niño. Has crecido más grande.",
  ui_story_5058_50581502_71_dialog_content = "¡Crecí! ¡Quiero ser tan grande como tú, mamá!",
  ui_story_5058_50581502_72_dialog_content = "Oh y...",
  ui_story_5058_50581502_73_dialog_content = "Confío en esta joven! ¡Si no fuera por ella, me habría caído del árbol y nunca habría vuelto a ver a mamá!",
  ui_story_5058_50581502_74_dialog_content = "La pequeña mariposa... ¿aterrizó en Lorelei?!",
  ui_story_5058_50581502_75_dialog_content = "...",
  ui_story_5058_50581502_76_dialog_content = "Entonces debemos darle nuestra más sincera gratitud.",
  ui_story_5058_50581502_77_dialog_content = "¿Quieres que... extienda mi mano?",
  ui_story_5058_50581502_78_dialog_content = "¿Eh? ¿Es este el capullo del que acaba de salir esa pequeña mariposa?",
  ui_story_5058_50581502_79_dialog_content = "Me disculpo por incapacitar a tu mamá. El fluido dentro del capullo es el antídoto.",
  ui_story_5058_50581502_80_dialog_content = "Nos trasladaremos más profundo al valle. Creo que tú cumplirás con tu promesa.",
  ui_story_5058_50581502_81_dialog_content = "¿Es este... el moco del que hablaba Cena? ¡Gracias, Diosa Denuo! ¡Gracias!",
  ui_story_5058_50581502_82_dialog_content = "¡Prometo que cumpliré con mi palabra!",
  ui_story_5058_50581502_83_dialog_content = "Buena suerte.",
  ui_story_5058_50581502_84_dialog_content = "Lorelei... ¿¡Tú recibiste la bendición de la Diosa Denuo?!",
  ui_story_5058_50581502_85_dialog_content = "Tú...",
  ui_story_5058_50581502_86_dialog_content = "Oh... Diosa Denuo, Cena ha estado protegiendo el valle conmigo todo este tiempo! No es tan malo como dice ser...",
  ui_story_5058_50581502_87_dialog_content = "Por favor, no—",
  ui_story_5058_50581502_88_dialog_content = "¿Ah?",
  ui_story_5058_50581502_89_dialog_content = "<color=#e8d9bb>La Diosa Denuo tocó las alas transparentes en la espalda de Cena.</color>",
  ui_story_5058_50581502_90_dialog_content = "Silbido... Ahora me veo diferente y tú también, pero aún recuerdo esas alas.",
  ui_story_5058_50581502_91_dialog_content = "Qué hermoso par de alas es.",
  ui_story_5058_50581502_92_dialog_content = "Gracias por liberarme de la telaraña antes.",
  ui_story_5058_50581502_93_dialog_content = "Eso... ¿Eras tú?",
  ui_story_5058_50581502_94_dialog_content = "Esa tormenta de arena de hace doce años no tuvo nada que ver con nosotros, y lo siento por tu sufrimiento.",
  ui_story_5058_50581502_95_dialog_content = "Siempre te he estado buscando, no para castigarte sino para agradecerte.",
  ui_story_5058_50581502_96_dialog_content = "Gracias por darme otra vida, y que encuentres el propósito de la tuya.",
  ui_story_5058_50581502_97_dialog_content = "Yo-yo lo haré...",
  ui_story_5058_50581502_98_dialog_content = "Espero con muchas ganas ver a su niño con alas tan espectaculares como las suyas.",
  ui_story_5058_50581502_99_dialog_content = "Aparte de Luke, nadie ha apreciado mis alas de esa manera...",
  ui_story_5058_50581502_100_dialog_content = "Es hora de irnos, mi niño.",
  ui_story_5058_50581502_101_dialog_content = "¡Espérame, mamá!",
  ui_story_5058_50581502_102_dialog_content = "Se fue, ¿así nomás?",
  ui_story_5058_50581502_103_dialog_content = "¿Eh? ¿Todos los Eclipsites de por aquí también se han ido?!",
  ui_story_5058_50581502_104_dialog_content = "Así que... ¿ya terminó todo? EveTodo sucedió tan de repente, ni siquiera he tenido la oportunidad de procesarlo todo...",
  ui_story_5058_50581502_105_dialog_content = "Jaja... ¡Jajajajaja!",
  ui_story_5058_50581502_106_dialog_content = "¿Cuál es la gran idea, Cena?! No empieces a reír así de repente, me estás asustando...",
  ui_story_5058_50581502_107_dialog_content = "No pude evitar reírme de mí mismo. EveAunque claramente tengo estas alas en mi espalda, aún no pude descifrar lo que la Diosa Denuo estaba pensando, después de todo este tiempo.",
  ui_story_5058_50581502_108_dialog_content = "Ya seas una Diosa Denuo, un insecto promedio o un demi-humano como yo, todos somos muy simples en el fondo.",
  ui_story_5058_50581502_109_dialog_content = "Y mientras no les hagas daño, nunca atacarán sin provocación.",
  ui_story_5058_50581502_110_dialog_content = "Pueden olvidar mil rencores en una noche, pero recordarán un solo acto de bondad de por vida.",
  ui_story_5058_50581502_111_dialog_content = "¿Incluso pueden olvidar sus rencores?",
  ui_story_5058_50581502_112_dialog_content = "Cena, ¿qué te dijo la Diosa Denuo antes de irse?",
  ui_story_5058_50581502_113_dialog_content = "Ella me bendijo con...",
  ui_story_5058_50581502_114_dialog_content = "El valor para seguir viviendo.",
  ui_story_5058_50581601_1_dialog_content = "¡¿Qué dijiste?!",
  ui_story_5058_50581601_2_dialog_content = "¿Eliminar todo el bombo relacionado con la Diosa Denuo?",
  ui_story_5058_50581601_3_dialog_content = "Como estimados inversionistas, este es el primer asunto que quería traer a su atención hoy.",
  ui_story_5058_50581601_4_dialog_content = "El segundo asunto que me gustaría informarles es que no continuaré con el desarrollo de Denuo Incense, y en tercer lugar, ahora puedo confirmar que la segunda fase del plan de expansión del complejo turístico ha sido cancelada en todos los aspectos.",
  ui_story_5058_50581601_5_dialog_content = "¿Sabes lo que estás diciendo?",
  ui_story_5058_50581601_6_dialog_content = "¡Los tres son la mejor manera de garantizar que el complejo recuperará la inversión y seguirá funcionando! ¿Puedes dirigir un negocio?",
  ui_story_5058_50581601_7_dialog_content = "Je, no te preocupes por eso ahora mismo. Por lo que parece... tienes otros planes bajo la manga, ¿verdad jefe?",
  ui_story_5058_50581601_8_dialog_content = "Sé que esto podría ser difícil de aceptar al principio, pero después de una cuidadosa consideración, he decidido que el Denuo Valley Resort debería operar bajo una filosofía de negocio más consciente.",
  ui_story_5058_50581601_9_dialog_content = "Ya sea en marketing, servicios o productos de origen local, debemos tener en cuenta el concepto de sostenibilidad del valle en todo momento y seguir un principio rector de desarrollo ecológico.",
  ui_story_5058_50581601_10_dialog_content = "Las actividades mencionadas podrían generar ganancias a corto plazo, pero no abordan el impacto que estamos causando en el medio ambiente y las consecuencias que surgirán tarde o temprano.",
  ui_story_5058_50581601_11_dialog_content = "Por eso propongo que sigamos mejorando el entorno dentro del valle y forjemos un ecosistema donde los Aurorianos, animales y plantas puedan coexistir...",
  ui_story_5058_50581601_12_dialog_content = "¿Seguir mejorando el medio ambiente? ¿Todo eso solo para sacarnos más dinero?",
  ui_story_5058_50581601_13_dialog_content = "Según mis cálculos, las ganancias de la operación básica del complejo turístico, menos varios gastos, deberían ser suficientes para respaldar mi plan propuesto!",
  ui_story_5058_50581601_14_dialog_content = "¿Nos tomas por tontos? ¡Ya has obtenido tanto de nosotros! ¿Crees que esto es una caridad?",
  ui_story_5058_50581601_15_dialog_content = "He realizado una serie de pruebas preliminares y estoy totalmente seguro de que la nueva encarnación del resort será un éxito garantizado. ¡Todo lo que necesitamos hacer es abrir las puertas y ver cómo los huéspedes entran en masa!",
  ui_story_5058_50581601_16_dialog_content = "Primero, necesitamos esforzarnos al máximo para establecer una buena reputación, asegurar ganancias para el período actual y mejorar continuamente el ambiente en el valle...",
  ui_story_5058_50581601_17_dialog_content = "Una vez que estemos seguros de que el entorno natural del valle se puede preservar completamente, podemos construir una reserva de vida silvestre para que nuestros huéspedes disfruten.",
  ui_story_5058_50581601_18_dialog_content = "No solo proporcionará a nuestros huéspedes una experiencia única y novedosa, sino que también garantizará que el complejo ofrezca un entorno idílico para todos los que lo visiten.",
  ui_story_5058_50581601_19_dialog_content = "Y con eso, nuestro complejo tendrá una sólida ventaja competitiva sobre todos los Astra!",
  ui_story_5058_50581601_20_dialog_content = "No hace falta decir que todo esto garantiza obtener grandes rendimientos en tus inversiones a largo plazo.",
  ui_story_5058_50581601_21_dialog_content = "Jejeje... Es tan bueno verte plasmando tus propias ideas y simplemente siguiéndolas, Lorelei!",
  ui_story_5058_50581601_22_dialog_content = "¡Siempre he sido de los que animan y apoyan el espíritu emprendedor cuando lo veo!",
  ui_story_5058_50581601_23_dialog_content = "Even si mi inversión no generará ganancias pronto, no me importa... No me importa esperar un par de días más para mi dinero.",
  ui_story_5058_50581601_24_dialog_content = "Continuaré supervisando tu progreso, por supuesto, para asegurarme de que te mantengas en el camino correcto y hagas lo que te propusiste lograr. De lo contrario, también podría tener que retirar mi soporte.",
  ui_story_5058_50581601_25_dialog_content = "¡Ridículo! ¿Y el resto de ustedes? ¡No creo que sigan cayendo en este proyecto estúpido!",
  ui_story_5058_50581601_26_dialog_content = "Tómalo con calma. Estoy feliz por ella y sus ideas.",
  ui_story_5058_50581601_27_dialog_content = "Sin embargo... Tú sabes que lo que estás haciendo ahora claramente viola el contrato que firmamos, ¿verdad, Lorelei?",
  ui_story_5058_50581601_28_dialog_content = "De acuerdo con los términos, tienes que pagarnos el triple por la violación.",
  ui_story_5058_50581601_29_dialog_content = "Seguro, eso es correcto. ¿Puedes pagarlo, Lorelei?",
  ui_story_5058_50581601_30_dialog_content = "Yo...",
  ui_story_5058_50581601_31_dialog_content = "¿¡S-Solo tres veces más?! Ahhh... ¿Qué se supone que le diga a papá ahora?!",
  ui_story_5058_50581601_32_dialog_content = "Frota sal en las heridas de un amigo firme, y seguro que encontrarás un final pegajoso.",
  ui_story_5058_50581601_33_dialog_content = "Si nos hubieras dicho esto desde el principio, Lorelei, nunca habríamos invertido...",
  ui_story_5058_50581601_34_dialog_content = "Sí, yo tampoco...",
  ui_story_5058_50581601_35_dialog_content = "No te preocupes, Lorelei!",
  ui_story_5058_50581601_36_dialog_content = "¿A quiénes creen todos ustedes que están menospreciando? No es como si nosotros no pudiéramos pagarlo—",
  ui_story_5058_50581601_37_dialog_content = "...",
  ui_story_5058_50581601_38_dialog_content = "Ejem... Estoy cien por ciento seguro de que mi hija puede manejar esto con un brazo atado detrás de su espalda!",
  ui_story_5058_50581601_39_dialog_content = "(Mamá...)",
  ui_story_5058_50581601_40_dialog_content = "Sinceramente pido disculpas a todos ustedes, y estoy completamente consciente de que mis acciones violaron los términos de nuestro contrato original.",
  ui_story_5058_50581601_41_dialog_content = "Asumo toda la responsabilidad y no intentaré pasar la pelota.",
  ui_story_5058_50581601_42_dialog_content = "Pero también necesito que todos ustedes crean que mi determinación para reconstruir el valle es tan inquebrantable como mi determinación para dirigir un excelente complejo turístico!",
  ui_story_5058_50581601_43_dialog_content = "Estoy completamente seguro de que puedo obtener mejores rendimientos en sus inversiones. Es solo que... tal vez necesite esperar un poco más de lo esperado.",
  ui_story_5058_50581601_44_dialog_content = "Entiendo y te aplaudo.",
  ui_story_5058_50581601_45_dialog_content = "Pero le pediré a mi abogado que te envíe una factura, Lorelei.",
  ui_story_5058_50581601_46_dialog_content = "No digas que nunca te dimos una oportunidad... Comienza a preocuparte por tu bancarrota.",
  ui_story_5058_50581601_47_dialog_content = "Laurie...",
  ui_story_5058_50581601_48_dialog_content = "Uf... Está bien, mamá. Pensé que las cosas podrían salir de esta manera.",
  ui_story_5058_50581601_49_dialog_content = "Pero aún no ha terminado. No usaré la fortuna familiar para compensar la diferencia hasta que al menos pida ayuda al gremio primero...",
  ui_story_5058_50581601_50_dialog_content = "Bueno, no tiene sentido intentar detener a un rebelde empedernido como tú.",
  ui_story_5058_50581601_51_dialog_content = "Jaja, no estás equivocado... pero sé que estoy haciendo lo correcto, y eso es suficiente para mí.",
  ui_story_5058_50581601_52_dialog_content = "Me gusta que tampoco puedas soportar a esos viejos cascarrabias.",
  ui_story_5058_50581601_53_dialog_content = "Sé de un cierto tonto que aparentemente tiene más de unos cuantos Nightium de sobra, y un séquito de tamaño razonable además.",
  ui_story_5058_50581601_54_dialog_content = "Si supiera que invertí aquí, estoy seguro de que se desviviría por aportar aún más financiamiento que yo.",
  ui_story_5058_50581601_55_dialog_content = "¡Por favor promete que me la presentarás!",
  ui_story_5058_50581601_56_dialog_content = "¡Sus alas brillaban como una gema bajo la luz solar!",
  ui_story_5058_50581601_57_dialog_content = "Vaya, debería haber ido con ustedes...",
  ui_story_5058_50581601_58_dialog_content = "Hmm, ¿no dijiste que es mejor tener un problema menos que un dolor de cabeza más, y luego dormir como un tronco?",
  ui_story_5058_50581601_59_dialog_content = "¿Es mi culpa que la cama del hotel sea tan suave y huela tan malditamente bien? Nunca antes había dormido en una cuna tan cómoda...",
  ui_story_5058_50581601_60_dialog_content = "No importa... Fia y yo estamos trabajando como expertos senior en animales para el resort, así que tal vez aún tengamos la oportunidad de conocer a la Diosa Denuo algún día pronto.",
  ui_story_5058_50581601_61_dialog_content = "Maestro, ¿de verdad planeas desperdiciar tus días aquí para siempre?",
  ui_story_5058_50581601_62_dialog_content = "PlayerName, ¿qué sigues haciendo aquí charlando?",
  ui_story_5058_50581601_63_dialog_content = "Mira, ¡Carleen y yo ya hemos guardado un montón de pegatinas!",
  ui_story_5058_50581601_64_dialog_content = "Realmente han revolucionado su campaña de marketing, incluso las mariposas en estas pegatinas han sido reemplazadas...",
  ui_story_5058_50581601_65_dialog_content = "Pero las reglas son las mismas que antes: simplemente acumula suficientes pegatinas y podrás canjearlas por premios.",
  ui_story_5058_50581601_66_dialog_content = "Escuchamos que el premio mayor es un pase anual para el complejo turístico Denuo Valley Resort.",
  ui_story_5058_50581601_67_dialog_content = "Si no ahorras suficientes pegatinas, PlayerName... ¡Simplemente tomaré Carleen la próxima vez! ¡Ni siquiera me molestaré en preguntarte!",
  ui_story_5058_50581601_68_dialog_content = "¿De verdad irías sin mí?",
  ui_story_5058_50581601_69_dialog_content = "Ejem... Mira, si no quieres perderte la diversión, ¡ven a jugar con nosotros a Fantasy Matrix!",
  ui_story_5058_50581601_70_dialog_content = "¿Qué? ¿Todavía estás jugando con esa cosa?!",
  ui_story_5058_50581601_71_dialog_content = "Aquí tienes un consejo gratis: la próxima vez, ni siquiera pienses en dejar que Sinsa diseñe una atracción de parque temático...",
  ui_story_5058_50581601_72_dialog_content = "Lo encontré.",
  ui_story_5058_50581601_73_dialog_content = "Cena, ¿no has hecho suficiente?",
  ui_story_5058_50581601_74_dialog_content = "¿Por fin puedes pasar el rato con nosotros hoy?",
  ui_story_5058_50581601_75_dialog_content = "Señoras, ¡gracias a todas por la gran cantidad de comentarios perspicaces y sugerencias que han propuesto para el complejo!",
  ui_story_5058_50581601_76_dialog_content = "Siguiendo sus deseos, Lorelei me ha pedido que acelere los ajustes en el equipamiento y diversos servicios del complejo turístico según sus sugerencias.",
  ui_story_5058_50581601_77_dialog_content = "Algo es diferente en Cena...",
  ui_story_5058_50581601_78_dialog_content = "¿Eh? ¿En serio? ¿Nunca les he mostrado a ustedes, señoras, mi lado genial y competente antes?",
  ui_story_5058_50581601_79_dialog_content = "¿Te has encontrado?",
  ui_story_5058_50581601_80_dialog_content = "No.",
  ui_story_5058_50581601_81_dialog_content = "Vaya... Eso fue brutal, Winona. Jaja...",
  ui_story_5058_50581601_82_dialog_content = "Cena, ¡no te dejes llevar charlando con los invitados! Recuerda, ¡tenemos mucho trabajo por hacer!",
  ui_story_5058_50581601_83_dialog_content = "Oh, cierto... Casi lo había olvidado...",
  ui_story_5058_50581601_84_dialog_content = "Señoras, ¡debo salir! Por favor, no me extrañen demasiado, podemos recordar los viejos tiempos luego.",
  ui_story_5058_50581601_85_dialog_content = "¿Deberíamos seguir esperando?",
  ui_story_5058_50581601_86_dialog_content = "Nah, parecía lo suficientemente bien como para que dejáramos de preocuparnos.",
  ui_story_5058_50581601_87_dialog_content = "Qué pena. ¿Qué tal si vamos a ver el Celestita?",
  ui_story_5058_50581601_88_dialog_content = "Oye, esa no es una mala idea.",
  ui_story_5058_50581601_89_dialog_content = "¿Mmm? ¡Solo me fui un minuto a buscar un helado de lagarto! ¿Dónde se fue todos?",
  ui_story_5058_50581601_90_dialog_content = "<size=45>¿Me olvidaron de nuevo?!</size>",
  ui_story_5058_50581601_91_dialog_content = "La primera vez que te llevé a la rueda del cielo, apenas podías ver la vista, incluso de pie.",
  ui_story_5058_50581601_92_dialog_content = "¡Lo recuerdo, lo recuerdo! Estaba realmente enojado y comencé a quejarme de que la rueda del cielo no había sido diseñada correctamente y que quería quejarme con el gerente.",
  ui_story_5058_50581601_93_dialog_content = "El personal dijo que me darían una muñeca para mantenerme feliz.",
  ui_story_5058_50581601_94_dialog_content = "Y de todas esas lindas muñecas que te pidieron elegir, ¡escogiste ese enorme esqueleto de animal que tenían en exhibición!",
  ui_story_5058_50581601_95_dialog_content = "¡Jajaja! Realmente no sé en qué estaba pensando en ese momento...",
  ui_story_5058_50581601_96_dialog_content = "Realmente no puedo creerlo... Mi pequeña Laurie ha crecido tanto.",
  ui_story_5058_50581601_97_dialog_content = "Mamá, gracias por estar ahí para mí en la reunión de la junta hoy.",
  ui_story_5058_50581601_98_dialog_content = "Si no te hubiera tenido allí, no creo que hubiera tenido la confianza para salir adelante.",
  ui_story_5058_50581601_99_dialog_content = "No seas ridícula, ¡eres mi hija! ¿Qué clase de madre no apoyaría a su hija, eh?!",
  ui_story_5058_50581601_100_dialog_content = "Y sé que incluso si no estuviera allí para apoyarte, tienes la capacidad de lograr cualquier cosa que te propongas.",
  ui_story_5058_50581601_101_dialog_content = "Como cuando valientemente le pediste a la Diosa Denuo un antídoto y me salvaste...",
  ui_story_5058_50581601_102_dialog_content = "Si no fuera por ti, quizás nunca hubiera podido hacer las paces con la Diosa Denuo.",
  ui_story_5058_50581601_103_dialog_content = "Así es. Tal vez toda esta experiencia fue una oportunidad otorgada por los cielos, o quizás por la propia Diosa Denuo...",
  ui_story_5058_50581601_104_dialog_content = "Estaba atrapado en una larga y dolorosa pesadilla, un sueño en el que me vi obligado a enfrentarme a mi verdadero yo.",
  ui_story_5058_50581601_105_dialog_content = "Fue entonces cuando me di cuenta de que no había sido una buena madre para ti...",
  ui_story_5058_50581601_106_dialog_content = "No te conté sobre tu ciudad natal y tus seres queridos, e incluso estaba obstaculizando tu crecimiento...",
  ui_story_5058_50581601_107_dialog_content = "Mamá, ¡no digas eso de ti misma!",
  ui_story_5058_50581601_108_dialog_content = "Soy la chica más afortunada del mundo, ¿y sabes por qué? ¡Porque tengo dos mamás amables y hermosas!",
  ui_story_5058_50581601_109_dialog_content = "Vaya, vaya, vaya... Si ustedes dos quieren tener una charla de madre e hija, está perfectamente bien, pero ¿por qué me están metiendo en esto?",
  ui_story_5058_50581601_110_dialog_content = "Le dije a las señoras que volvería enseguida! Esas hermosas niñas me están esperando, ¡por amor de Dios!",
  ui_story_5058_50581601_111_dialog_content = "Por supuesto que tenía que llevarte conmigo.",
  ui_story_5058_50581601_112_dialog_content = "¿Has olvidado la promesa entre tú, yo y Coco?",
  ui_story_5058_50581601_113_dialog_content = "¿Promesa? ¿Qué promesa?",
  ui_story_5058_50581601_114_dialog_content = "Oh, está a punto de comenzar... Tres... dos...",
  ui_story_5058_50581601_115_dialog_content = "¡Uno!",
  ui_story_5058_50581601_116_dialog_content = "<color=#e8d9bb>¡Whoosh—Bang!</color>",
  ui_story_5058_50581601_117_dialog_content = "Es...",
  ui_story_5058_50581601_118_dialog_content = "¿Un espectáculo de fuegos artificiales?",
  ui_story_5058_50581601_119_dialog_content = "<color=#e8d9bb>¡Zummm—¡Boom, boom!</color>",
  ui_story_5058_50581601_120_dialog_content = "\"Los fuegos artificiales se lanzaron al cielo nocturno como mariposas revoloteando...\"",
  ui_story_5058_50581601_121_dialog_content = "¿Son realmente tan hermosos los fuegos artificiales en Lumopolis?",
  ui_story_5058_50581601_122_dialog_content = "¡Escuché que son incluso más hermosas que las mariposas!",
  ui_story_5058_50581601_123_dialog_content = "Mamá, ¡también quiero ir a Lumopolis para ver los fuegos artificiales!",
  ui_story_5058_50581601_124_dialog_content = "¡Pero Lumopolis está muy, muy lejos!",
  ui_story_5058_50581601_125_dialog_content = "¿De qué hay que tener miedo? ¡Vamos a verlos juntos! ¡Sé que llegaremos allí algún día!",
  ui_story_5058_50581601_126_dialog_content = "¿En serio? ¿No extrañan ustedes dos el hogar?",
  ui_story_5058_50581601_127_dialog_content = "Dondequiera que estés, Coco, ahí es donde está mi hogar.",
  ui_story_5058_50581601_128_dialog_content = "¡Hey! ¿Estás intentando robarme a mi mamá, Cena?! ¡Ni siquiera lo pienses! ¡Mamá es toda mía!",
  ui_story_5058_50581601_129_dialog_content = "¡Ni siquiera estoy intentando decir que Coco es mi mamá!",
  ui_story_5058_50581601_130_dialog_content = "E-Ella es... ¡una dama encantadora!",
  ui_story_5058_50581601_131_dialog_content = "Jaja, sí suena divertido tener un hijo de la misma edad que tú!",
  ui_story_5058_50581601_132_dialog_content = "¡Sra. Coco! ¡La dama más encantadora que conozco!",
  ui_story_5058_50581601_133_dialog_content = "Luke, hace tanto tiempo que no sé de ti.",
  ui_story_5058_50581601_134_dialog_content = "\"¡Nunca adivinarás dónde estoy trabajando ahora!\"",
  ui_story_5058_50581601_X134_dialog_content = "\"¡Estoy trabajando en Denuo Valley Resort—el lugar que mencionaste en tu carta!\"",
  ui_story_5058_50581601_135_dialog_content = "Si te dijera que el Valle Denuo es el misterioso lugar de origen del que te hablé antes,\n¿cuán sorprendido estarías?",
  ui_story_5058_50581601_136_dialog_content = "\"Pero tengo algo aún más impactante que contarte...\"",
  ui_story_5058_50581601_X136_dialog_content = "\"¡Vi a la Diosa Denuo!\"",
  ui_story_5058_50581601_137_dialog_content = "Y eso es correcto, ¡SALÍ VIVO! Sé lo que estás pensando ahora mismo, \"¿Por qué escribió que sigue vivo en mayúsculas?\"",
  ui_story_5058_50581601_138_dialog_content = "Lamentablemente, no puedo incluir todos los detalles en una sola carta...",
  ui_story_5058_50581601_139_dialog_content = "Si tienes tiempo, simplemente tienes que venir a visitarme al complejo turístico. Te estaré esperando y listo para compartir todas mis experiencias desde que regresé a mi ciudad natal.",
  ui_story_5058_50581601_140_dialog_content = "\"EveTodas las noches antes de cerrar mis ojos para dormir, espero con ansias lo que el mañana pueda traer. Se siente...\"",
  ui_story_5058_50581601_X140_dialog_content = "<size=45>\"¡Increíble!\"</size>"
}
return config
